import { BankEntry, OwnSubject } from "@/types/plano";

export const PREFEITURA_9_ANO_THEME_BANK: Record<OwnSubject, BankEntry[]> = {
  matematica: [
    {"theme":"Transformando dízima periódica em fração geratriz","curriculumCode":"EF09M01","description":"Aula que ensina o procedimento para descobrir a fração geradora de uma dízima periódica, retomando a ideia de número racional.","materials":["Calculadora","Fichas com dízimas periódicas variadas","Quadro para resolução coletiva"],"steps":["Apresentar uma dízima periódica simples e questionar se ela pode ser escrita como fração.","Demonstrar coletivamente o procedimento algébrico para obter a fração geratriz.","Praticar o procedimento com uma dízima periódica composta.","Organizar duplas para encontrar a fração geratriz de novas dízimas.","Conferir os resultados dividindo a fração encontrada na calculadora.","Sistematizar o procedimento no caderno com um exemplo resolvido passo a passo."]},
    {"theme":"Naturais, inteiros, racionais e irracionais: o conjunto dos reais","curriculumCode":"EF09M02","description":"Aula que relaciona os diferentes campos numéricos já estudados, levando à compreensão do conjunto dos números reais como união dos racionais e irracionais.","materials":["Cartaz com diagrama de conjuntos numéricos","Fichas com números variados (inteiros, frações, decimais, radicais)","Quadro"],"steps":["Retomar rapidamente os conjuntos numéricos já conhecidos (naturais, inteiros, racionais).","Apresentar exemplos de números que não são racionais e discutir onde eles se encaixam.","Construir coletivamente um diagrama de inclusão mostrando os reais como união de racionais e irracionais.","Organizar grupos para classificar fichas numéricas dentro do diagrama.","Corrigir coletivamente, discutindo casos que geram dúvidas.","Registrar o diagrama final no caderno com exemplos próprios."]},
    {"theme":"Quando a resposta não é um número racional","curriculumCode":"EF09M03","description":"Aula que discute situações, especialmente ligadas à geometria e a medidas, cujas soluções não podem ser expressas por números racionais, como os casos de π, √2 e √3.","materials":["Régua e compasso","Quadrado de papel para construir a diagonal","Calculadora"],"steps":["Propor a construção da diagonal de um quadrado de lado 1 e medir seu comprimento.","Discutir por que essa medida não corresponde a uma fração exata conhecida.","Apresentar o caso do π ao calcular a razão entre comprimento e diâmetro de um círculo.","Organizar grupos para investigar outras situações geométricas com resultados semelhantes.","Sistematizar coletivamente por que essas medidas são chamadas de irracionais.","Encerrar com um registro dos exemplos discutidos em aula."]},
    {"theme":"Números irracionais na reta numérica","curriculumCode":"EF09M04","description":"Aula que caracteriza um número irracional como aquele cuja representação decimal é infinita e não periódica, estimando a posição de alguns deles na reta numerada.","materials":["Fita métrica ou barbante para reta numérica no chão","Calculadora com função raiz quadrada","Fichas com números irracionais"],"steps":["Apresentar exemplos de números irracionais e suas representações decimais aproximadas.","Discutir a diferença entre decimal finita, periódica e não periódica.","Estimar coletivamente entre quais inteiros está a raiz de um número não quadrado perfeito.","Organizar duplas para posicionar números irracionais na reta numerada do chão.","Conferir as estimativas com a calculadora.","Fechar com uma reflexão sobre a densidade dos números reais na reta."]},
    {"theme":"Calculando com números irracionais e tecnologia digital","curriculumCode":"EF09M05","description":"Aula que constrói procedimentos de cálculo envolvendo números irracionais, usando recursos digitais para obter aproximações sucessivas aos números racionais.","materials":["Calculadora científica ou aplicativo","Computador ou celular com acesso à internet (opcional)","Fichas com operações envolvendo radicais"],"steps":["Apresentar uma operação simples envolvendo um número irracional, como √2 + 3.","Discutir estratégias de aproximação por tentativa antes de usar a tecnologia.","Demonstrar o uso da calculadora para obter aproximações cada vez mais precisas.","Organizar duplas para resolver operações com irracionais usando a tecnologia disponível.","Comparar os resultados obtidos por diferentes níveis de aproximação.","Encerrar com uma discussão sobre quando uma aproximação é suficiente na prática."]},
    {"theme":"Resolvendo problemas com números reais","curriculumCode":"EF09M06","description":"Aula que analisa, interpreta e resolve problemas envolvendo os diferentes significados das operações no campo dos números reais.","materials":["Lista de problemas contextualizados","Calculadora","Quadro para resolução coletiva"],"steps":["Apresentar um problema que combine números racionais e irracionais.","Discutir coletivamente qual operação e qual significado ela assume na situação.","Resolver o problema modelo, registrando o raciocínio no quadro.","Organizar grupos para resolver uma lista variada de problemas com números reais.","Corrigir coletivamente, comparando as estratégias usadas por diferentes grupos.","Fechar com uma discussão sobre a razoabilidade dos resultados obtidos."]},
    {"theme":"Porcentagens sucessivas, taxas percentuais e juros simples","curriculumCode":"EF09M07","description":"Aula que analisa, formula e resolve problemas envolvendo porcentagens sucessivas, além da determinação de taxas percentuais e do cálculo de juros simples.","materials":["Anúncios com descontos ou acréscimos sucessivos","Calculadora","Fichas com situações de juros simples"],"steps":["Apresentar uma situação com dois descontos sucessivos e discutir se o resultado é igual à soma dos percentuais.","Resolver coletivamente o cálculo correto de percentuais sucessivos.","Retomar a fórmula de juros simples com um problema modelo.","Organizar duplas para resolver problemas de taxas percentuais e juros simples.","Corrigir coletivamente, destacando erros comuns nesse tipo de cálculo.","Encerrar com uma reflexão sobre o uso de porcentagens sucessivas em promoções comerciais."]},
    {"theme":"Representando a variação de duas grandezas","curriculumCode":"EF09M08","description":"Aula que representa e caracteriza a variação conjunta de duas grandezas, analisando seu comportamento em diferentes situações.","materials":["Fichas com pares de grandezas relacionadas (tempo e distância, preço e quantidade)","Papel quadriculado","Régua"],"steps":["Apresentar uma situação em que duas grandezas variam juntas, como tempo e distância percorrida.","Construir coletivamente uma tabela de valores para a situação.","Representar os dados em um gráfico, observando o comportamento da variação.","Organizar grupos para representar novas situações com pares de grandezas diferentes.","Comparar os formatos de gráfico obtidos entre os grupos.","Sistematizar as características de cada tipo de variação observada."]},
    {"theme":"Interseção e declive: relacionando expressões algébricas e gráficos","curriculumCode":"EF09M09","description":"Aula que relaciona expressões algébricas a suas representações gráficas no plano cartesiano, explorando os significados de interseção entre retas e de declive.","materials":["Plano cartesiano impresso ou software de geometria dinâmica","Régua","Fichas com expressões algébricas lineares"],"steps":["Apresentar duas expressões algébricas lineares e seus respectivos gráficos.","Identificar coletivamente o ponto de interseção entre as retas no plano.","Discutir o que o declive de cada reta representa na expressão algébrica.","Organizar duplas para explorar novos pares de expressões usando régua ou tecnologia digital.","Verificar algebricamente o ponto de interseção encontrado graficamente.","Encerrar com uma síntese sobre a relação entre coeficientes e comportamento gráfico."]},
    {"theme":"Resolvendo equações do 2º grau por diferentes estratégias","curriculumCode":"EF09M10","description":"Aula que resolve e elabora problemas representados por equações polinomiais de 2º grau, discutindo o significado das soluções e explorando fatoração e cálculo mental quando possível.","materials":["Fichas com equações do 2º grau variadas","Quadro para resolução coletiva","Calculadora"],"steps":["Apresentar um problema que se traduz em uma equação do 2º grau.","Explorar a resolução por fatoração quando a equação permitir.","Demonstrar a fórmula resolutiva para casos mais complexos.","Organizar duplas para resolver problemas variados, escolhendo a estratégia mais adequada.","Discutir coletivamente o significado das raízes encontradas no contexto de cada problema.","Fechar com uma reflexão sobre quando uma solução deve ser descartada por não fazer sentido prático."]},
    {"theme":"Operando com frações algébricas","curriculumCode":"EF09M11","description":"Aula que constrói procedimentos de cálculo para operar com frações algébricas, estabelecendo analogias com os procedimentos já conhecidos das frações numéricas.","materials":["Fichas com frações algébricas simples","Quadro para resolução coletiva"],"steps":["Retomar rapidamente como se somam e simplificam frações numéricas.","Apresentar uma fração algébrica e discutir a analogia com o procedimento numérico.","Demonstrar coletivamente a soma e a simplificação de frações algébricas simples.","Organizar duplas para praticar operações com frações algébricas em fichas de exercícios.","Corrigir coletivamente, retomando os pontos de maior dificuldade.","Encerrar com um registro comparativo entre os dois tipos de fração."]},
    {"theme":"Sistemas de equações do 1º e do 2º graus em problemas","curriculumCode":"EF09M12","description":"Aula que analisa, formula e resolve problemas que envolvem sistemas de equações do primeiro e do segundo graus.","materials":["Lista de problemas contextualizados","Quadro para resolução coletiva","Calculadora"],"steps":["Apresentar uma situação-problema que gera um sistema combinando equações de 1º e 2º graus.","Traduzir a situação para o sistema de equações coletivamente.","Demonstrar um método de resolução do sistema misto.","Organizar grupos para traduzir e resolver novos problemas semelhantes.","Corrigir coletivamente, validando as soluções no contexto de cada problema.","Fechar com uma discussão sobre estratégias diferentes de resolução usadas pelos grupos."]},
    {"theme":"Analisando padrões e funções com expressões, tabelas e gráficos","curriculumCode":"EF09M13","description":"Aula que analisa e representa padrões e funções por meio de expressões algébricas, palavras, tabelas e gráficos, integrando diferentes formas de representação.","materials":["Fichas com sequências numéricas e padrões visuais","Papel quadriculado","Régua"],"steps":["Apresentar uma sequência numérica ou visual e pedir que descrevam o padrão com palavras.","Guiar a turma na tradução do padrão para uma expressão algébrica.","Construir uma tabela de valores a partir da expressão obtida.","Representar os valores da tabela em um gráfico.","Organizar grupos para repetir o processo com novos padrões.","Sistematizar como as quatro formas de representação (palavras, expressão, tabela, gráfico) se relacionam."]},
    {"theme":"Explorando vistas e secções de figuras espaciais","curriculumCode":"EF09M14","description":"Aula que explora, representa e descreve diferentes vistas de figuras geométricas espaciais e as secções obtidas ao cortá-las por planos, considerando a posição relativa de arestas e faces.","materials":["Sólidos geométricos (cubos, prismas, pirâmides)","Lanterna para projetar sombras","Papel para desenhar vistas"],"steps":["Apresentar um sólido geométrico e observar suas vistas frontal, lateral e superior.","Desenhar coletivamente as três vistas do sólido apresentado.","Simular um corte por um plano usando um sólido de massa de modelar ou isopor.","Descrever a figura plana obtida na secção realizada.","Organizar grupos para repetir o processo com sólidos diferentes.","Encerrar com uma exposição comparando as vistas e secções encontradas por cada grupo."]},
    {"theme":"Teorema de Pitágoras e relações métricas no triângulo retângulo","curriculumCode":"EF09M15","description":"Aula que investiga as relações métricas em um triângulo retângulo, expressando-as algebricamente e aplicando o Teorema de Pitágoras na resolução de problemas.","materials":["Régua e esquadro","Papel quadriculado para construção de quadrados sobre os lados","Calculadora"],"steps":["Construir um triângulo retângulo e os quadrados sobre seus três lados em papel quadriculado.","Comparar as áreas dos quadrados construídos, chegando à relação pitagórica.","Formalizar algebricamente o Teorema de Pitágoras a partir da investigação.","Organizar duplas para resolver problemas que apliquem o teorema.","Corrigir coletivamente, discutindo situações práticas de uso (escadas, rampas, telhados).","Fechar com um registro da fórmula e de um exemplo resolvido."]},
    {"theme":"Semelhança de polígonos e o Teorema de Tales","curriculumCode":"EF09M16","description":"Aula que investiga e expressa as condições para que polígonos sejam semelhantes, explorando o Teorema de Tales para resolver problemas de proporcionalidade entre segmentos.","materials":["Régua","Malha quadriculada ou papel para desenhos proporcionais","Fichas com problemas de semelhança"],"steps":["Apresentar dois polígonos semelhantes e medir seus lados e ângulos correspondentes.","Investigar coletivamente as condições que garantem a semelhança.","Demonstrar o Teorema de Tales com retas paralelas cortadas por transversais.","Organizar grupos para resolver problemas que apliquem semelhança e o Teorema de Tales.","Corrigir coletivamente, retomando as condições de semelhança usadas.","Encerrar com exemplos de aplicação prática, como cálculo de alturas inacessíveis."]},
    {"theme":"Arcos, ângulos centrais e ângulos inscritos na circunferência","curriculumCode":"EF09M17","description":"Aula que reconhece e utiliza arcos, ângulos centrais e ângulos inscritos em uma circunferência, estabelecendo relações entre eles com apoio de softwares de geometria dinâmica ou instrumentos tradicionais.","materials":["Compasso e transferidor","Software de geometria dinâmica (opcional)","Papel para construções"],"steps":["Construir uma circunferência e marcar um ângulo central com o compasso e o transferidor.","Marcar um ângulo inscrito que subentenda o mesmo arco do ângulo central.","Medir e comparar os dois ângulos, investigando a relação entre eles.","Organizar duplas para repetir a investigação com arcos diferentes.","Sistematizar coletivamente a relação entre ângulo central e ângulo inscrito.","Fechar com a resolução de problemas que apliquem essa relação."]},
    {"theme":"Reflexão, rotação e translação na criação de ornamentos","curriculumCode":"EF09M18","description":"Aula que explora a criação de ornamentos no plano por meio da identificação de reflexões em reta (simetria axial), rotações e translações aplicadas a uma figura geométrica.","materials":["Malha quadriculada","Papel vegetal ou transparência","Lápis de cor"],"steps":["Apresentar exemplos de ornamentos e padrões visuais que usam simetria e repetição.","Identificar coletivamente quais transformações geométricas formam cada padrão.","Demonstrar como reflexão, rotação e translação combinadas criam um ornamento.","Organizar grupos para criar seu próprio ornamento aplicando as três transformações.","Expor as criações e identificar coletivamente as transformações usadas em cada uma.","Encerrar com uma discussão sobre onde esses padrões aparecem no cotidiano (azulejos, tecidos)."]},
    {"theme":"Média, moda, mediana e amplitude de uma pesquisa","curriculumCode":"EF09M19","description":"Aula que calcula as medidas de tendência central (média, moda e mediana) de uma pesquisa estatística, compreendendo seus significados e relacionando-os com a dispersão dos dados indicada pela amplitude.","materials":["Dados de uma pesquisa realizada com a turma","Calculadora","Quadro para organização dos dados"],"steps":["Coletar ou apresentar um conjunto de dados de uma pesquisa simples.","Calcular coletivamente a média, a moda e a mediana do conjunto.","Calcular a amplitude e discutir o que ela indica sobre a dispersão dos dados.","Organizar grupos para comparar dois conjuntos de dados diferentes usando essas medidas.","Discutir em quais situações cada medida de tendência central é mais representativa.","Fechar com uma síntese sobre a relação entre as medidas e a variabilidade dos dados."]},
    {"theme":"Probabilidade de eventos a partir do espaço amostral","curriculumCode":"EF09M20","description":"Aula que resolve problemas envolvendo noções de espaço amostral e de probabilidade de ocorrência de um evento.","materials":["Dados, moedas ou cartas para experimentos","Fichas com problemas de probabilidade","Calculadora"],"steps":["Retomar rapidamente a construção de um espaço amostral com um exemplo simples.","Calcular coletivamente a probabilidade de um evento nesse espaço amostral.","Organizar duplas para resolver problemas mais elaborados de probabilidade.","Realizar um experimento prático para comparar frequência observada e probabilidade calculada.","Corrigir coletivamente, discutindo diferenças entre teoria e prática.","Encerrar com uma reflexão sobre situações do cotidiano que envolvem probabilidade."]},
    {"theme":"Planejando e comunicando uma pesquisa amostral sobre a realidade social","curriculumCode":"EF09M21","description":"Aula que orienta o planejamento e a realização de uma pesquisa amostral sobre um tema da realidade social, com comunicação dos resultados por meio de relatório contendo medidas de tendência central, amplitude, tabelas e gráficos.","materials":["Formulário de pesquisa","Planilha eletrônica ou papel para tabelas e gráficos","Cartolina para o relatório final"],"steps":["Definir coletivamente um tema de realidade social relevante para a pesquisa.","Planejar a amostra e elaborar o questionário da pesquisa.","Coletar os dados junto à amostra definida.","Calcular as medidas de tendência central e a amplitude dos dados coletados.","Organizar os resultados em tabelas e gráficos, com apoio de planilha eletrônica quando possível.","Produzir e apresentar um relatório final com as conclusões da pesquisa."]},
    {"theme":"Identificando erros de leitura em gráficos","curriculumCode":"EF09M22","description":"Aula que analisa e identifica elementos que podem induzir a erros de leitura em gráficos, como escalas inapropriadas, legendas mal explicadas e omissão de informações importantes.","materials":["Exemplos de gráficos com falhas (escalas cortadas, legendas ausentes)","Reportagens ou notícias com gráficos","Quadro para anotações"],"steps":["Apresentar um gráfico com uma escala manipulada ou legenda ausente.","Discutir coletivamente qual leitura equivocada esse gráfico pode induzir.","Analisar outros exemplos de gráficos, identificando fontes e datas ausentes.","Organizar grupos para encontrar exemplos de gráficos com problemas em jornais ou internet.","Propor que cada grupo reconstrua o gráfico de forma correta.","Fechar com uma discussão sobre a importância da leitura crítica de gráficos."]},
    {"theme":"Escolhendo e construindo o gráfico mais adequado","curriculumCode":"EF09M23","description":"Aula que seleciona e constrói o gráfico mais adequado (colunas, setores ou linhas) para apresentar um conjunto de dados, inclusive com uso de planilhas eletrônicas, destacando as medidas de tendência central.","materials":["Conjuntos de dados variados","Computador com planilha eletrônica (ou papel quadriculado)","Régua"],"steps":["Apresentar um conjunto de dados e discutir qual tipo de gráfico melhor o representa.","Construir coletivamente esse gráfico, com ou sem uso de planilha eletrônica.","Destacar no gráfico as medidas de tendência central calculadas anteriormente.","Organizar grupos para escolher e construir o gráfico adequado para um novo conjunto de dados.","Comparar as escolhas feitas por diferentes grupos para o mesmo tipo de dado.","Encerrar com uma síntese dos critérios usados para escolher cada tipo de gráfico."]},
    {"theme":"Calculando o volume de prismas e cilindros retos","curriculumCode":"EF09M24","description":"Aula que resolve e elabora problemas envolvendo o cálculo de medidas de volume de prismas e de cilindros retos.","materials":["Modelos ou embalagens em formato de prisma e cilindro","Fita métrica","Calculadora"],"steps":["Apresentar um prisma e discutir como calcular seu volume a partir da área da base.","Repetir o raciocínio para um cilindro reto, relacionando com a área do círculo da base.","Medir objetos reais em formato de prisma e cilindro e calcular seus volumes.","Organizar duplas para elaborar e resolver problemas envolvendo esses volumes.","Corrigir coletivamente, comparando as unidades de medida usadas.","Fechar com uma discussão sobre aplicações práticas, como capacidade de embalagens."]},
    {"theme":"Notação científica para medidas muito grandes ou muito pequenas","curriculumCode":"EF09M25","description":"Aula que reconhece e emprega unidades que expressam medidas muito grandes ou muito pequenas, fazendo uso da notação científica.","materials":["Exemplos de medidas astronômicas e microscópicas","Calculadora científica","Fichas com números para conversão"],"steps":["Apresentar exemplos de medidas muito grandes (distância entre estrelas) e muito pequenas (tamanho de uma célula).","Demonstrar como escrever esses números em notação científica.","Praticar coletivamente conversões entre notação decimal e científica.","Organizar duplas para resolver operações envolvendo números em notação científica.","Conferir os resultados com a calculadora científica.","Encerrar com um desafio de leitura rápida de medidas em notação científica."]},
    {"theme":"Calculando perímetro e área de superfícies planas compostas","curriculumCode":"EF09M26","description":"Aula que constrói e utiliza procedimentos para o cálculo de áreas e perímetros de superfícies planas limitadas por segmentos de reta e por arcos de circunferência.","materials":["Figuras compostas desenhadas em papel quadriculado","Régua e compasso","Calculadora"],"steps":["Apresentar uma figura composta por retas e arcos de circunferência.","Decompor coletivamente a figura em partes conhecidas (retângulos, triângulos, setores circulares).","Calcular a área e o perímetro somando as partes decompostas.","Organizar duplas para calcular área e perímetro de novas figuras compostas.","Corrigir coletivamente, comparando as estratégias de decomposição usadas.","Fechar com um desafio de criar uma figura composta e calcular suas medidas."]},
    {"theme":"Área de superfície de cubo, bloco retangular e pirâmides","curriculumCode":"EF09M27","description":"Aula que resolve problemas envolvendo o cálculo da área de superfície de cubos, blocos retangulares e pirâmides, a partir da planificação dessas figuras.","materials":["Moldes de planificação de cubo, bloco retangular e pirâmide","Tesoura e cola","Régua"],"steps":["Planificar coletivamente um cubo e identificar as faces que compõem sua superfície.","Calcular a área de superfície do cubo somando a área das faces.","Repetir o processo para um bloco retangular e para uma pirâmide.","Organizar grupos para montar e calcular a área de superfície de sólidos com moldes.","Corrigir coletivamente, comparando os resultados obtidos.","Encerrar com uma discussão sobre aplicações práticas, como cálculo de material para embalagens."]},
    {"theme":"Calculando o volume de cubos e paralelepípedos a partir das medidas","curriculumCode":"EF09M28","description":"Aula que resolve e elabora problemas envolvendo o cálculo de volumes de cubos e paralelepípedos a partir de suas medidas.","materials":["Cubos e blocos de material concreto ou moldes de papel","Fita métrica","Calculadora"],"steps":["Apresentar um cubo e medir a aresta para calcular seu volume.","Repetir o processo para um paralelepípedo, medindo suas três dimensões.","Discutir coletivamente a diferença entre volume de cubo e de paralelepípedo.","Organizar duplas para elaborar problemas envolvendo o cálculo desses volumes.","Trocar os problemas elaborados entre as duplas para resolução.","Fechar com uma correção coletiva e discussão das estratégias usadas."]},
    {"theme":"Perímetro e diâmetro: a razão constante da circunferência","curriculumCode":"EF09M29","description":"Aula que estabelece a relação entre a medida do perímetro e a medida do diâmetro de uma circunferência, aproximando-se do valor de π.","materials":["Objetos circulares de tamanhos diferentes","Barbante e régua","Calculadora"],"steps":["Medir com barbante o perímetro de vários objetos circulares.","Medir o diâmetro de cada objeto e registrar os valores em uma tabela.","Calcular coletivamente a razão entre perímetro e diâmetro para cada objeto.","Discutir por que esse valor se aproxima de uma constante em todos os casos.","Organizar grupos para repetir a medição com novos objetos e confirmar o padrão.","Encerrar apresentando o π como essa razão constante."]},
    {"theme":"Calculando a área de círculos","curriculumCode":"EF09M30","description":"Aula que calcula a área de círculos, aplicando a fórmula obtida a partir da relação com o raio.","materials":["Círculos recortados em papel quadriculado","Tesoura","Calculadora"],"steps":["Recortar um círculo em setores e reorganizá-los para aproximar um retângulo.","Relacionar as dimensões desse retângulo aproximado com o raio e a circunferência do círculo original.","Deduzir coletivamente a fórmula da área do círculo a partir dessa aproximação.","Organizar duplas para calcular a área de círculos de raios diferentes.","Corrigir coletivamente, conferindo os cálculos com a calculadora.","Fechar com problemas práticos envolvendo área de superfícies circulares."]},
    {"theme":"Razão entre grandezas diferentes: velocidade e densidade demográfica","curriculumCode":"EF09M31","description":"Aula que resolve problemas envolvendo a razão entre duas grandezas de espécies diferentes, como velocidade e densidade demográfica.","materials":["Fichas com dados de distância, tempo, população e área","Calculadora","Mapa ou dados populacionais de cidades"],"steps":["Retomar a ideia de velocidade como razão entre distância e tempo.","Apresentar a densidade demográfica como razão entre população e área.","Resolver coletivamente um problema envolvendo cada uma dessas grandezas.","Organizar duplas para resolver novos problemas com razões entre grandezas diferentes.","Corrigir coletivamente, discutindo a unidade de medida resultante em cada razão.","Encerrar com uma pesquisa rápida comparando a densidade demográfica de duas cidades."]},
    {"theme":"Comprimento da circunferência e sua relação com o diâmetro","curriculumCode":"EF09M32","description":"Aula que investiga a relação existente entre o comprimento de uma circunferência e a medida do seu diâmetro, retomando e aprofundando essa razão constante.","materials":["Objetos circulares de tamanhos variados","Barbante e régua","Calculadora"],"steps":["Medir novamente o comprimento e o diâmetro de diferentes objetos circulares.","Organizar os dados em uma tabela e calcular a razão entre as duas medidas.","Comparar os resultados obtidos por diferentes duplas, verificando a proximidade do valor de π.","Discutir coletivamente por que essa relação se mantém constante, independentemente do tamanho do círculo.","Formalizar a expressão que relaciona comprimento e diâmetro usando π.","Fechar com uma síntese registrada no caderno."]},
    {"theme":"Calculando o comprimento de uma circunferência","curriculumCode":"EF09M33","description":"Aula que resolve problemas envolvendo o cálculo da medida do comprimento de uma circunferência, aplicando a fórmula obtida a partir da relação com o diâmetro.","materials":["Fichas com problemas de circunferências","Calculadora","Objetos circulares para conferência prática"],"steps":["Retomar a fórmula do comprimento da circunferência a partir do diâmetro ou do raio.","Resolver coletivamente um problema modelo aplicando a fórmula.","Organizar duplas para resolver uma lista de problemas variados.","Propor uma conferência prática medindo o comprimento real de um objeto circular.","Corrigir coletivamente, comparando o valor calculado com o valor medido.","Encerrar com uma discussão sobre aplicações práticas do cálculo de comprimento circular."]},
    {"theme":"Jogos de estratégia para praticar cálculo mental","curriculumCode":"EF09M34","description":"Aula lúdica que propõe jogos envolvendo estratégias e procedimentos de cálculo mental, consolidando a agilidade de cálculo dos estudantes.","materials":["Dados ou cartas numeradas","Cronômetro","Tabuleiro ou marcador de pontuação"],"steps":["Explicar as regras de um jogo que exige respostas rápidas de cálculo mental.","Organizar a turma em duplas ou pequenos grupos para as primeiras rodadas.","Circular pela sala observando as estratégias mentais utilizadas pelos alunos.","Promover uma rodada de socialização sobre os atalhos de cálculo mais eficientes.","Propor uma rodada final com desafios mais complexos.","Fechar com uma reflexão sobre como o jogo contribuiu para a agilidade de cálculo."]},
    {"theme":"Jogos de percepção de regularidades e generalização","curriculumCode":"EF09M35","description":"Aula lúdica que propõe jogos envolvendo estratégias de percepção de regularidades e o processo de generalização, conectando o lúdico ao pensamento algébrico.","materials":["Cartas, peças ou fichas com sequências e padrões","Tabuleiro ou registro de jogadas"],"steps":["Apresentar um jogo em que a vitória depende de perceber um padrão nas jogadas.","Organizar a turma em duplas para jogar algumas rodadas.","Pedir que os alunos registrem o padrão percebido durante o jogo.","Discutir coletivamente como generalizar esse padrão para prever jogadas futuras.","Relacionar a estratégia do jogo com a ideia de generalização usada em álgebra.","Encerrar com uma rodada final aplicando a generalização identificada."]},
    {"theme":"Projeto sobre o impacto social e econômico das mudanças climáticas","curriculumCode":"EF09M36","description":"Aula que inicia um projeto envolvendo o impacto social e econômico relacionado às mudanças climáticas, relacionando o tema com conceitos matemáticos.","materials":["Reportagens ou dados sobre impactos econômicos das mudanças climáticas","Cartolina para planejamento do projeto","Calculadora"],"steps":["Apresentar dados sobre impactos econômicos e sociais de eventos climáticos extremos.","Discutir coletivamente como a matemática pode ajudar a analisar esses impactos (gráficos, porcentagens, médias).","Organizar grupos para escolher um recorte específico do tema para investigar.","Orientar os grupos na coleta e organização de dados relacionados ao recorte escolhido.","Acompanhar a produção de gráficos ou tabelas com os dados levantados.","Propor uma apresentação parcial dos projetos em desenvolvimento."]},
    {"theme":"Projeto sobre migração e mudanças climáticas","curriculumCode":"EF09M37","description":"Aula que desenvolve um projeto envolvendo a migração e a fuga de populações relacionadas às mudanças climáticas, utilizando a matemática para analisar dados sobre o tema.","materials":["Dados ou reportagens sobre migração climática","Mapa mundo ou regional","Cartolina para apresentação"],"steps":["Apresentar exemplos de migrações motivadas por mudanças climáticas.","Discutir coletivamente como interpretar dados numéricos sobre esse fenômeno (quantidades, porcentagens, taxas).","Organizar grupos para pesquisar um caso específico de migração climática.","Orientar a produção de gráficos ou mapas com os dados coletados por cada grupo.","Acompanhar a elaboração das conclusões de cada grupo com base nos dados levantados.","Encerrar com uma apresentação dos projetos e debate coletivo sobre os resultados."]},
    {"theme":"Elaborando um projeto de pesquisa com método científico (TCA)","curriculumCode":"EF09M38","description":"Aula que orienta a elaboração de um projeto de pesquisa envolvendo conhecimentos matemáticos, usando o método científico como subsídio para o Trabalho Colaborativo de Autoria (TCA).","materials":["Exemplos de projetos de pesquisa anteriores","Papel para registro do planejamento do projeto","Roteiro de etapas do método científico"],"steps":["Apresentar as etapas básicas de um projeto de pesquisa usando o método científico.","Discutir coletivamente como a matemática pode ser incorporada a um tema de pesquisa do TCA.","Organizar grupos para escolher um tema de pesquisa relacionado a conhecimentos matemáticos.","Orientar cada grupo na formulação de uma pergunta de pesquisa e no planejamento das etapas.","Acompanhar o início da investigação, apoiando na coleta e organização de dados.","Encerrar com uma apresentação do planejamento de cada grupo para o restante da turma."]},
  ],
  "lingua-portuguesa": [
    {"theme":"Contos e crônicas: mergulhando em diferentes universos narrativos","curriculumCode":"EF09LP01","description":"Aula de leitura comparada de contos de diferentes subgêneros (fantástico, policial, ficção científica, noir) e crônicas, com foco em como a organização interna e o estilo mudam conforme o tipo de narrativa.","materials":["Coletânea de contos de diferentes subgêneros","Crônicas impressas","Quadro comparativo","Post-its coloridos"],"steps":["Apresentar brevemente as características de cada subgênero de conto trabalhado","Dividir a turma em grupos, cada um recebendo um conto de subgênero diferente","Pedir que identifiquem marcas linguísticas e de estilo próprias do subgênero lido","Promover rodízio de grupos para que todos conheçam os diferentes textos","Ler uma crônica em conjunto e comparar sua estrutura com a dos contos","Fechar com debate sobre o que diferencia esses gêneros narrativos entre si"]},
    {"theme":"Leitura programada de uma obra literária extensa","curriculumCode":"EF09LP02","description":"Sequência de leitura de um romance ou obra extensa dividida em etapas ao longo do bimestre, com paradas guiadas para discutir recursos discursivos e posicionamento crítico dos estudantes.","materials":["Exemplares da obra escolhida (físicos ou digitais)","Roteiro de leitura por capítulos","Diário de leitura do estudante","Cronograma de leitura"],"steps":["Apresentar a obra escolhida e o cronograma de leitura programada","Definir trechos a serem lidos entre um encontro e outro","Conduzir rodas de conversa periódicas sobre os trechos lidos","Destacar recursos e estratégias discursivas do gênero em cada etapa","Estimular os estudantes a registrar reações e opiniões no diário de leitura","Fechar com um debate final sobre os efeitos de sentido da obra completa"]},
    {"theme":"Resenhas em diálogo: comparando críticas sobre uma mesma obra","curriculumCode":"EF09LP03","description":"Aula de comparação entre resenhas escritas sobre obras literárias lidas pela turma e as opiniões manifestadas nas discussões coletivas em sala, identificando valores em jogo.","materials":["Resenhas literárias selecionadas","Registro das discussões anteriores da turma","Quadro branco","Folhas para anotações"],"steps":["Retomar as principais opiniões da turma sobre a obra discutida anteriormente","Distribuir resenhas escritas por críticos sobre a mesma obra","Pedir que os estudantes identifiquem os valores defendidos em cada resenha","Comparar em grupo as resenhas com as opiniões da turma","Discutir coletivamente pontos de convergência e divergência","Solicitar que cada estudante escreva um parágrafo posicionando-se criticamente"]},
    {"theme":"Vozes em conflito: comparando posicionamentos sobre representações sociais","curriculumCode":"EF09LP04","description":"Aula de leitura comparativa de textos que tratam do mesmo tema social sob perspectivas diferentes, identificando pontos de vista, valores éticos e políticos envolvidos.","materials":["Conjunto de textos com posicionamentos divergentes sobre um tema social","Quadro comparativo","Canetas coloridas"],"steps":["Escolher um tema social atual com representações sociais em disputa","Distribuir textos com pontos de vista diferentes sobre o tema","Pedir que os grupos identifiquem os valores éticos e políticos de cada texto","Preencher um quadro comparativo com pontos de vista e argumentos","Promover debate estruturado entre os diferentes posicionamentos","Encerrar com reflexão escrita individual sobre o próprio ponto de vista"]},
    {"theme":"Textos multimodais em projetos interdisciplinares","curriculumCode":"EF09LP05","description":"Aula que analisa textos multimodais (imagem, som, texto) usados em projetos interdisciplinares, discutindo os valores éticos e estéticos veiculados e o papel de cada linguagem na construção de sentido.","materials":["Textos multimodais de diferentes áreas do conhecimento","Projetor","Ficha de análise multimodal"],"steps":["Selecionar textos multimodais ligados a um projeto interdisciplinar em curso","Apresentar os textos e identificar as linguagens que os compõem","Discutir em grupo os valores éticos e estéticos presentes em cada linguagem","Analisar como as linguagens se articulam para formar sentido conjunto","Registrar as conclusões em uma ficha de análise multimodal","Compartilhar as análises com a turma"]},
    {"theme":"Aprofundando o tema: leitura articulada de textos complementares","curriculumCode":"EF09LP06","description":"Aula sobre relações de consumo e sustentabilidade em que os estudantes articulam uma leitura inicial a textos complementares de outros gêneros, aprofundando o tema e posicionando-se criticamente.","materials":["Texto inicial sobre consumo e sustentabilidade","Textos complementares de gêneros variados","Cartazes para síntese"],"steps":["Ler coletivamente um texto inicial sobre relações de consumo e sustentabilidade","Apresentar textos complementares de gêneros distintos sobre o mesmo tema","Pedir que os grupos articulem as informações dos diferentes textos","Identificar valores éticos, estéticos, afetivos e políticos presentes nos textos","Produzir um cartaz-síntese com a posição crítica do grupo","Expor os cartazes e discutir as conclusões em plenária"]},
    {"theme":"Pesquisando com fontes múltiplas: leitura para estudar temas interdisciplinares","curriculumCode":"EF09LP07","description":"Aula de pesquisa em que os estudantes leem textos de diferentes áreas do conhecimento em fontes variadas (livros, sites, revistas, documentários) para estudar um tema e analisá-lo criticamente.","materials":["Acesso a biblioteca ou internet","Lista de fontes recomendadas","Roteiro de pesquisa","Caderno de anotações"],"steps":["Definir um tema de estudo interdisciplinar com a turma","Apresentar diferentes tipos de fonte disponíveis para pesquisa","Organizar grupos de pesquisa, cada um explorando um tipo de fonte","Orientar o registro das informações encontradas em cada fonte","Reunir os grupos para articular as informações coletadas","Promover análise crítica coletiva sobre a confiabilidade das fontes usadas"]},
    {"theme":"Oficina de minicontos autorais","curriculumCode":"EF09LP08","description":"Aula de produção escrita de minicontos a partir de repertório literário prévio dos estudantes, com atenção à progressão temática, coesão e coerência.","materials":["Exemplos de minicontos","Folhas para rascunho","Lista de verificação de coesão e coerência"],"steps":["Apresentar exemplos de minicontos e discutir suas características","Levantar com a turma repertório de temas e referências literárias prévias","Solicitar a escrita de um primeiro rascunho de miniconto","Trabalhar em duplas a revisão da progressão temática e coesão","Reescrever o texto considerando os apontamentos da revisão","Organizar uma leitura compartilhada dos minicontos finalizados"]},
    {"theme":"Haicai e poema concreto: da produção ao vídeo para o sarau","curriculumCode":"EF09LP09","description":"Aula de produção de haicai, poema visual e/ou concreto respeitando as características do gênero, culminando na gravação de um vídeo para apresentação em sarau escolar.","materials":["Exemplos de haicai e poemas visuais/concretos","Papel e materiais de desenho","Celular ou câmera para gravação"],"steps":["Apresentar exemplos de haicai e de poemas visuais/concretos","Discutir as características formais de cada gênero poético","Orientar a produção individual ou em duplas de um poema","Revisar o poema quanto à forma e à situação comunicativa definida","Ensaiar a leitura ou apresentação do poema para gravação","Gravar os vídeos e organizar a exibição no sarau da escola"]},
    {"theme":"Artigo de divulgação científica: comunicando ciência ao público","curriculumCode":"EF09LP10","description":"Aula de produção de artigo de divulgação científica sobre um tema de interesse da turma, respeitando as características do gênero e a situação comunicativa.","materials":["Exemplos de artigos de divulgação científica","Fontes de pesquisa sobre o tema escolhido","Roteiro de estrutura do gênero"],"steps":["Analisar coletivamente um artigo de divulgação científica modelo","Levantar as características estruturais e de linguagem do gênero","Escolher com a turma temas científicos de interesse para produção","Pesquisar informações confiáveis sobre o tema escolhido","Redigir o artigo respeitando a estrutura e a situação comunicativa","Revisar em pares e publicar os artigos em um mural ou blog da turma"]},
    {"theme":"Artigo de opinião: defendendo um ponto de vista com argumentos","curriculumCode":"EF09LP11","description":"Aula de produção de artigo de opinião sobre um tema atual, respeitando o conteúdo temático, o movimento argumentativo típico do gênero e as etapas de produção textual.","materials":["Artigos de opinião de jornais e revistas","Lista de temas atuais para escolha","Ficha de planejamento argumentativo"],"steps":["Ler e analisar um artigo de opinião como modelo de gênero","Identificar o movimento argumentativo típico do texto (tese, argumentos, conclusão)","Escolher um tema atual e planejar os argumentos a serem usados","Produzir o rascunho do artigo de opinião individualmente","Revisar o texto verificando coerência argumentativa","Compartilhar os artigos finalizados em roda de leitura"]},
    {"theme":"Comentários opinativos sobre temas atuais para o mural da escola","curriculumCode":"EF09LP12","description":"Aula de escrita de comentários opinativos curtos sobre matérias jornalísticas atuais, destinados a compor murais de classe, corredores ou publicações digitais da escola.","materials":["Matérias jornalísticas impressas e/ou digitais","Papel para mural","Canetinhas"],"steps":["Selecionar matérias jornalísticas sobre temas atuais relevantes à turma","Ler e discutir coletivamente as matérias escolhidas","Solicitar que cada estudante escreva um comentário opinativo curto","Revisar os comentários quanto à clareza e adequação ao veículo de publicação","Montar um mural de classe ou corredor com os comentários","Divulgar também em espaço digital da escola, se disponível"]},
    {"theme":"Slam de poesia: apresentando textos poéticos ao vivo","curriculumCode":"EF09LP13","description":"Aula de preparação e apresentação de poemas, repentes, contendas e raps em formato de slam, considerando as características do evento comunicativo e a interação com o público.","materials":["Textos poéticos previamente selecionados ou produzidos","Microfone ou caixa de som (se disponível)","Espaço para apresentação"],"steps":["Apresentar exemplos de slams e discutir as regras do evento","Organizar a escolha ou produção dos poemas a serem apresentados","Ensaiar a performance considerando ritmo, voz e postura","Definir papéis: apresentador, participantes e comissão avaliadora","Realizar o slam seguindo o formato de abertura, apresentações e encerramento","Promover uma roda de avaliação coletiva sobre as apresentações"]},
    {"theme":"Relato oral do andamento de uma pesquisa em curso","curriculumCode":"EF09LP14","description":"Aula em que os estudantes relatam oralmente o progresso de estudos ou pesquisas que estão desenvolvendo, apontando facilidades e dificuldades e pedindo orientação da turma e do professor.","materials":["Registros parciais das pesquisas dos estudantes","Roteiro de relato oral"],"steps":["Retomar brevemente as pesquisas em andamento na turma","Orientar os estudantes a organizar um roteiro de relato oral","Solicitar que cada estudante relate o andamento de seu trabalho","Destacar facilidades e dificuldades encontradas até o momento","Abrir espaço para comentários e sugestões dos colegas","Registrar as orientações recebidas para dar continuidade à pesquisa"]},
    {"theme":"Assembleia escolar: discutindo o cotidiano e temas da adolescência","curriculumCode":"EF09LP15","description":"Aula-assembleia em que a turma discute questões do cotidiano escolar e temas controversos ligados à puberdade e adolescência, ouvindo opiniões, argumentando e construindo sínteses coletivas.","materials":["Pauta de assembleia","Registro de assembleias anteriores (se houver)","Papel para anotação das sínteses"],"steps":["Levantar com a turma os temas a serem discutidos na assembleia","Organizar a mediação e a ordem de fala dos participantes","Conduzir a discussão dos temas do cotidiano escolar","Abrir espaço específico para temas ligados à adolescência e puberdade","Estimular a escuta das opiniões alheias antes de posicionar-se","Elaborar coletivamente uma síntese final das decisões e opiniões"]},
    {"theme":"Caçando argumentos: identificando teses e provas em textos argumentativos","curriculumCode":"EF09LP16","description":"Aula de análise de textos argumentativos com foco na identificação dos argumentos usados para sustentar a posição defendida pelo autor.","materials":["Textos argumentativos diversos","Marcadores de texto","Ficha de identificação de argumentos"],"steps":["Apresentar um texto argumentativo e identificar sua tese central","Pedir que os estudantes grifem os argumentos que sustentam a tese","Organizar em grupo os argumentos encontrados por tipo","Discutir a força e a pertinência de cada argumento identificado","Comparar os argumentos entre textos diferentes","Fechar com um pequeno relatório escrito sobre a análise feita"]},
    {"theme":"Negociando posições: o jogo de argumentos no texto","curriculumCode":"EF09LP17","description":"Aula sobre como textos argumentativos negociam posições com o leitor, reconhecendo a presença ou ausência dessa negociação e os argumentos que a sustentam.","materials":["Textos argumentativos com diferentes graus de negociação","Quadro para registro de observações"],"steps":["Explicar o conceito de negociação de posições em um texto argumentativo","Ler um texto que negocia abertamente com pontos de vista contrários","Ler um segundo texto mais categórico, sem negociação aparente","Comparar em grupo as estratégias usadas em cada texto","Identificar os argumentos que sustentam a negociação (ou sua ausência)","Debater qual estratégia é mais eficaz e em que contextos"]},
    {"theme":"Substituição e elipse: costurando o texto com coesão","curriculumCode":"EF09LP18","description":"Aula de análise linguística sobre os processos de substituição de palavras e de elipse, discutindo como esses recursos garantem a inteligibilidade do texto.","materials":["Trechos de textos com exemplos de substituição e elipse","Quadro branco","Lista de articuladores textuais"],"steps":["Apresentar um trecho de texto e identificar palavras repetidas","Mostrar como a substituição por outro item evita repetição desnecessária","Explicar o processo de elipse com exemplos do próprio trecho","Propor exercício de reescrita usando substituição e elipse","Corrigir coletivamente, discutindo o efeito na inteligibilidade","Aplicar o recurso na revisão de um texto produzido pela turma"]},
    {"theme":"Amarrando as partes do texto: coerência na produção escrita","curriculumCode":"EF09LP19","description":"Aula prática de revisão textual voltada a articular as partes de um texto de forma coerente, evitando problemas de compreensão durante a produção.","materials":["Rascunhos de textos produzidos pelos estudantes","Ficha de revisão de coerência"],"steps":["Retomar um texto em produção pela turma como exemplo","Identificar trechos em que a articulação entre partes não está clara","Discutir coletivamente possíveis ajustes para melhorar a coerência","Propor troca de rascunhos entre duplas para revisão cruzada","Reescrever trechos apontados como problemáticos","Socializar as melhorias percebidas após a revisão"]},
    {"theme":"Articuladores textuais em ação: costurando tempo, espaço e argumento","curriculumCode":"EF09LP20","description":"Aula sobre o reconhecimento e uso de articuladores textuais de ordenação temporal, espacial, lógico-semântica e argumentativa como recursos de coesão entre partes do texto.","materials":["Lista de articuladores textuais por categoria","Textos com articuladores destacados","Exercício de completar lacunas"],"steps":["Apresentar categorias de articuladores (tempo, espaço, lógico-semânticos, argumentativos)","Analisar um texto identificando os articuladores usados e sua função","Propor exercício de completar lacunas com articuladores adequados","Corrigir coletivamente, discutindo o efeito de cada escolha","Solicitar reescrita de um parágrafo próprio incorporando articuladores variados","Trocar textos em duplas para verificar o uso adequado dos articuladores"]},
    {"theme":"A vírgula em situações específicas de produção textual","curriculumCode":"EF09LP21","description":"Aula de análise linguística sobre o uso da vírgula em três situações específicas: elipse do verbo, orações ligadas por 'e' com sujeitos diferentes, e adversativas pospostas.","materials":["Frases-exemplo para cada regra de vírgula trabalhada","Quadro branco","Exercícios de pontuação"],"steps":["Apresentar a primeira regra (elipse do verbo) com exemplos","Apresentar a segunda regra (orações com 'e' e sujeitos diferentes)","Apresentar a terceira regra (adversativas pospostas)","Propor exercícios práticos de pontuação para cada situação","Corrigir coletivamente, esclarecendo dúvidas","Aplicar as regras na revisão de um texto autoral produzido pela turma"]},
    {"theme":"Escolhas de palavras: analisando o léxico dos próprios textos","curriculumCode":"EF09LP22","description":"Aula de revisão textual em que os estudantes analisam as escolhas lexicais feitas em seus próprios textos, verificando se estão adequadas às intenções de significação pretendidas.","materials":["Textos produzidos pelos próprios estudantes","Dicionário de sinônimos","Ficha de análise lexical"],"steps":["Retomar um texto produzido anteriormente pela turma","Destacar palavras-chave usadas no texto","Discutir se cada palavra escolhida transmite o sentido pretendido","Propor substituições e comparar os efeitos de sentido gerados","Solicitar que cada estudante revise o léxico do próprio texto","Compartilhar exemplos de melhorias lexicais encontradas"]},
    {"theme":"Dando voz ao outro: formas de citar o discurso alheio","curriculumCode":"EF09LP23","description":"Aula sobre as diferentes maneiras de citar o discurso de outras pessoas em textos argumentativos, como artigo de opinião, debate e comentário digital, e seus efeitos de sentido.","materials":["Textos argumentativos com diferentes formas de citação","Quadro comparativo de tipos de citação"],"steps":["Apresentar exemplos de citação direta e indireta em textos argumentativos","Identificar marcas linguísticas que sinalizam cada tipo de citação","Discutir o efeito de sentido de cada forma de citar o discurso alheio","Propor exercício de reescrita alternando entre citação direta e indireta","Aplicar uma forma de citação em um texto argumentativo próprio","Socializar os textos e discutir a escolha de citação de cada estudante"]},
    {"theme":"Sentido literal e figurado: denotação e conotação em ação","curriculumCode":"EF09LP24","description":"Aula de leitura voltada à análise dos efeitos de sentido gerados pelo emprego de palavras em sentido denotativo e conotativo em um texto.","materials":["Textos literários e não literários com exemplos de denotação e conotação","Ficha de análise de sentido"],"steps":["Relembrar as diferenças entre sentido denotativo e conotativo","Ler um texto com passagens de linguagem conotativa","Identificar coletivamente as palavras usadas em sentido figurado","Discutir os efeitos de sentido gerados por essas escolhas no texto","Propor que os estudantes reescrevam um trecho alternando denotação e conotação","Comparar os efeitos das duas versões produzidas"]},
    {"theme":"Revisando com recursos gráfico-textuais","curriculumCode":"EF09LP25","description":"Aula prática de revisão textual em que os estudantes aplicam recursos gráfico-textuais estudados ao longo do ano na produção ou revisão de seus próprios textos.","materials":["Textos em fase de revisão produzidos pela turma","Lista de recursos gráfico-textuais estudados"],"steps":["Retomar os recursos gráfico-textuais trabalhados ao longo do bimestre","Selecionar um texto coletivo para servir de exemplo de revisão","Aplicar em conjunto os recursos discutidos ao texto exemplo","Solicitar que cada estudante revise seu próprio texto usando os recursos","Trocar textos em duplas para checagem cruzada","Reunir a turma para socializar os ajustes realizados"]},
    {"theme":"Um português, muitas variedades: mapeando a diversidade linguística","curriculumCode":"EF09LP26","description":"Aula sobre a existência de variedades da língua portuguesa determinadas por fatores como classe social, idade, região e influências de povos indígenas, africanos e europeus.","materials":["Gravações ou textos exemplificando diferentes variedades linguísticas","Mapa do Brasil","Ficha de registro de variedades"],"steps":["Apresentar exemplos de fala ou textos de diferentes regiões e grupos sociais","Discutir os fatores que originam as variedades linguísticas apresentadas","Localizar no mapa a origem geográfica de cada variedade discutida","Explorar influências indígenas, africanas e europeias na língua portuguesa falada no Brasil","Organizar um mural coletivo com exemplos de variedades linguísticas","Refletir em grupo sobre a riqueza dessa diversidade"]},
    {"theme":"Qual variedade usar? Adequação linguística às situações comunicativas","curriculumCode":"EF09LP27","description":"Aula que discute quais variedades linguísticas são mais apropriadas a diferentes situações comunicativas, valorizando cada uma sem hierarquizá-las.","materials":["Situações comunicativas variadas descritas em cartões","Exemplos de fala formal e informal"],"steps":["Apresentar diferentes situações comunicativas em cartões (entrevista, conversa entre amigos, etc.)","Pedir que os grupos discutam qual variedade seria mais adequada a cada situação","Socializar as escolhas e justificativas de cada grupo","Discutir por que nenhuma variedade é superior às outras","Propor uma dramatização trocando a variedade conforme a situação muda","Fechar com reflexão sobre respeito à diversidade linguística"]},
    {"theme":"Preconceito linguístico: reconhecendo e combatendo a discriminação","curriculumCode":"EF09LP28","description":"Aula que discute situações de discriminação linguística contra falantes de variedades não-padrão, analisando a relação entre escolha linguística, situação comunicativa e seus efeitos sobre as pessoas.","materials":["Reportagens ou relatos sobre preconceito linguístico","Roda de discussão organizada em círculo"],"steps":["Apresentar um caso real ou relato de preconceito linguístico","Discutir em grupo as razões históricas e sociais desse preconceito","Relacionar a discriminação linguística com outras formas de discriminação social","Analisar os efeitos da discriminação na constituição da identidade das pessoas","Propor a escrita de um pequeno texto de posicionamento contra o preconceito linguístico","Compartilhar os textos produzidos em roda de conversa"]},
    {"theme":"A conjunção como conectora: relações entre sintagmas nominais e verbais","curriculumCode":"EF09LP29","description":"Aula de análise linguística sobre o papel da conjunção ao estabelecer relações entre sintagmas nominais e verbais, observando os efeitos de sentido gerados por esse uso.","materials":["Frases-exemplo com diferentes conjunções","Quadro branco","Exercício de análise sintática simplificada"],"steps":["Apresentar frases com diferentes conjunções conectando sintagmas","Identificar coletivamente a relação de sentido criada por cada conjunção","Propor troca de conjunções em uma mesma frase e comparar efeitos","Realizar exercício dirigido de identificação de conjunções em um texto","Discutir como a escolha da conjunção altera a interpretação do texto","Aplicar a análise a um trecho de produção textual da turma"]},
    {"theme":"A ordem dos pronomes: topologia pronominal no português falado no Brasil","curriculumCode":"EF09LP30","description":"Aula de análise linguística sobre as relações nos sintagmas verbais, com foco na posição dos pronomes (próclise, ênclise, mesóclise) e seus efeitos de sentido, considerando as variedades do português falado no Brasil.","materials":["Frases-exemplo com diferentes posições pronominais","Gravações de fala regional (se disponível)"],"steps":["Apresentar exemplos de frases com pronomes em diferentes posições","Explicar as regras de próclise, ênclise e mesóclise de forma contextualizada","Comparar o uso pronominal na norma padrão com o uso na fala coloquial brasileira","Propor exercício de reescrita de frases alterando a posição do pronome","Discutir os efeitos de sentido e de registro gerados por cada escolha","Fechar relacionando o conteúdo às variedades linguísticas já estudadas"]},
    {"theme":"Adjuntos adnominais e adverbiais: modificando nomes na oração","curriculumCode":"EF09LP31","description":"Aula de análise sintática voltada à compreensão da atuação das expressões modificadoras dos nomes e determinantes, com foco nos adjuntos adnominais e adverbiais.","materials":["Frases-exemplo com adjuntos destacados","Quadro branco","Exercício de identificação de termos acessórios"],"steps":["Retomar o conceito de termos acessórios da oração","Apresentar exemplos de adjuntos adnominais em frases","Apresentar exemplos de adjuntos adverbiais em frases","Propor exercício comparando a função de cada tipo de adjunto","Corrigir coletivamente, esclarecendo dúvidas de classificação","Aplicar a identificação em um trecho de texto autêntico"]},
    {"theme":"Vocativo e aposto: outros termos acessórios da oração","curriculumCode":"EF09LP32","description":"Aula de análise sintática sobre a atuação de nomes e determinantes nos termos acessórios da oração, com foco no vocativo e no aposto.","materials":["Frases-exemplo com vocativo e aposto destacados","Quadro branco"],"steps":["Apresentar exemplos de frases contendo vocativo","Apresentar exemplos de frases contendo aposto","Discutir as diferenças de função e de pontuação entre os dois termos","Propor exercício de identificação e classificação em um texto","Corrigir coletivamente as respostas","Solicitar que os estudantes criem frases próprias usando vocativo e aposto"]},
    {"theme":"Coordenação ou subordinação? Relações entre orações em períodos compostos","curriculumCode":"EF09LP33","description":"Aula de análise linguística sobre os diferentes tipos de relação (coordenação e subordinação) que as orações estabelecem entre si em períodos compostos, e os efeitos de sentido decorrentes.","materials":["Períodos compostos selecionados de textos diversos","Quadro branco","Ficha de classificação de orações"],"steps":["Retomar a diferença entre coordenação e subordinação de orações","Apresentar períodos compostos coordenados e pedir a identificação da relação","Apresentar períodos compostos subordinados e pedir a identificação da relação","Discutir os efeitos de sentido gerados por cada tipo de relação","Propor exercício de classificação em um texto autêntico","Corrigir coletivamente e esclarecer dúvidas remanescentes"]},
    {"theme":"Construindo períodos compostos na própria escrita","curriculumCode":"EF09LP34","description":"Aula prática de produção textual em que os estudantes empregam relações de coordenação e subordinação entre orações em seus próprios textos, considerando os efeitos de sentido gerados.","materials":["Rascunhos de textos autorais dos estudantes","Lista de conectivos coordenativos e subordinativos"],"steps":["Retomar os tipos de relação entre orações trabalhados anteriormente","Apresentar uma lista de conectivos coordenativos e subordinativos","Propor a reescrita de frases simples combinando-as em períodos compostos","Solicitar que os estudantes apliquem períodos compostos em um texto próprio","Revisar em duplas o uso adequado dos conectivos escolhidos","Socializar exemplos de períodos bem construídos com a turma"]},
    {"theme":"Regências em foco: analisando o período composto na revisão de textos","curriculumCode":"EF09LP35","description":"Aula de análise linguística sobre o emprego do período composto, identificando efeitos de sentido na escolha entre orações coordenadas ou subordinadas, com atenção a casos de regência nominal e verbal.","materials":["Trechos de textos com períodos compostos para análise","Lista de verbos e nomes com regência específica"],"steps":["Apresentar um trecho de texto com períodos compostos variados","Discutir os efeitos de sentido da escolha entre coordenação e subordinação","Introduzir casos de regência nominal e verbal presentes no trecho","Propor exercício de correção de regência em frases com erro proposital","Aplicar a análise na revisão de um texto produzido pela turma","Socializar as correções e dúvidas identificadas"]},
    {"theme":"Acento tônico em hiatos: as regras de acentuação gráfica","curriculumCode":"EF09LP36","description":"Aula de ortografia sobre as convenções de acentuação gráfica de palavras, com foco específico nas funções do acento tônico em hiatos.","materials":["Lista de palavras com hiatos acentuados e não acentuados","Quadro branco","Exercício de acentuação"],"steps":["Retomar o conceito de hiato com exemplos simples","Apresentar a regra de acentuação do hiato tônico","Propor exercício de identificação de palavras com hiato que exigem acento","Corrigir coletivamente, explicando cada caso","Aplicar a regra na revisão de um texto produzido pela turma","Fazer um ditado dirigido com palavras que contenham hiatos"]},
    {"theme":"Palavras difíceis: escrevendo corretamente irregularidades ortográficas","curriculumCode":"EF09LP37","description":"Aula de ortografia voltada a palavras que apresentam irregularidades (grafias que não seguem uma regra fixa), trabalhando estratégias de memorização e consulta.","materials":["Lista de palavras com irregularidades ortográficas comuns","Dicionário","Jogo de forca ou caça-palavras ortográfico"],"steps":["Levantar com a turma palavras de grafia frequentemente confundida","Explicar que essas palavras não seguem uma regra fixa, exigindo memorização","Apresentar estratégias como consulta ao dicionário e associação com palavras derivadas","Propor um jogo (forca ou caça-palavras) com as palavras irregulares levantadas","Realizar um ditado dirigido com essas palavras","Revisar coletivamente os erros mais comuns encontrados no ditado"]},
  ],
  ciencias: [
    {"theme":"Modelos atômicos ao longo da história","curriculumCode":"EF09C01","description":"Aula que percorre como diferentes modelos científicos explicaram a estrutura da matéria ao longo do tempo, mostrando que o conhecimento sobre átomos foi sendo construído e revisado.","materials":["Linha do tempo impressa","Imagens dos principais modelos atômicos (Dalton, Thomson, Rutherford, Bohr)","Bolinhas de isopor ou massinha","Cartolina"],"steps":["Perguntar aos alunos o que eles imaginam que existe dentro de um átomo.","Apresentar, em ordem cronológica, os principais modelos atômicos e o que cada um propunha.","Em grupos, construir uma representação física simples de um dos modelos com bolinhas ou massinha.","Comparar os modelos construídos, destacando o que mudou de um para outro.","Discutir por que o modelo atômico foi revisado várias vezes ao longo da história.","Fechar relacionando essa evolução à natureza da ciência como processo contínuo."]},
    {"theme":"Investigando a conservação de massa nas reações químicas","curriculumCode":"EF09C02","description":"Aula prática de investigação que testa se a massa total se mantém constante antes e depois de uma reação química, introduzindo a lei da conservação da massa.","materials":["Balança simples","Bicarbonato de sódio","Vinagre","Frasco com tampa ou balão de boca estreita","Copos medidores"],"steps":["Perguntar aos alunos o que acontece com a massa dos materiais depois de uma reação química.","Planejar em grupos um procedimento para pesar reagentes antes e produtos depois, mantendo o sistema fechado.","Realizar a reação entre bicarbonato e vinagre dentro de um recipiente vedado, pesando antes e depois.","Comparar os valores medidos e discutir eventuais diferenças encontradas.","Relacionar o resultado à lei de conservação da massa proposta por Lavoisier.","Registrar as conclusões da investigação em um relatório curto."]},
    {"theme":"Montando circuitos elétricos simples","curriculumCode":"EF09C03","description":"Aula investigativa em que os alunos planejam e montam circuitos elétricos básicos para entender como a eletricidade circula em equipamentos, eletrodomésticos e sistemas de iluminação.","materials":["Pilhas pequenas","Fios com garras jacaré","Lâmpadas ou LEDs de baixa voltagem","Interruptores simples","Fita isolante"],"steps":["Questionar os alunos sobre como a energia chega até uma lâmpada acesa em casa.","Explicar os elementos básicos de um circuito: fonte, condutor e receptor.","Em duplas, planejar e montar um circuito simples que acenda uma lâmpada.","Testar variações, como circuitos em série e em paralelo, e comparar o brilho das lâmpadas.","Relacionar o funcionamento do circuito montado a sistemas de iluminação residencial.","Discutir o que aconteceria se um dos fios fosse interrompido em cada tipo de circuito."]},
    {"theme":"Como a energia elétrica é produzida: a matriz energética brasileira","curriculumCode":"EF09C04","description":"Aula que constrói modelos explicativos sobre as transformações de energia envolvidas na geração de eletricidade e apresenta a composição da matriz energética do Brasil.","materials":["Gráfico ou tabela da matriz energética brasileira","Imagens de usinas hidrelétricas, termelétricas, eólicas e solares","Cartolina","Canetinhas"],"steps":["Perguntar de onde os alunos acham que vem a energia elétrica que usam em casa.","Apresentar diferentes tipos de usina e a transformação de energia envolvida em cada uma.","Em grupos, desenhar um esquema simples mostrando a sequência de transformações de energia de uma fonte escolhida.","Apresentar dados sobre a matriz energética brasileira e identificar a fonte predominante.","Comparar as fontes quanto à disponibilidade e ao impacto ambiental.","Sistematizar em um cartaz coletivo as transformações estudadas."]},
    {"theme":"Consumo de energia elétrica em casa: fazendo contas para economizar","curriculumCode":"EF09C05","description":"Aula que usa raciocínio matemático para comparar o consumo de energia de diferentes equipamentos residenciais e embasar decisões de compra mais econômicas.","materials":["Etiquetas de consumo (kWh) de aparelhos domésticos","Calculadora","Exemplo de conta de luz","Folha de exercícios"],"steps":["Apresentar uma conta de luz real ou fictícia e identificar o que é cobrado.","Explicar o que significa a potência de um aparelho em watts e o consumo em kWh.","Em grupos, calcular o consumo mensal estimado de dois aparelhos diferentes.","Comparar o custo de usar um aparelho mais e menos eficiente para a mesma função.","Argumentar, com base nos cálculos, qual equipamento seria mais vantajoso comprar.","Elaborar uma lista de dicas de economia baseada nos cálculos feitos."]},
    {"theme":"Prevenção de acidentes elétricos","curriculumCode":"EF09C06","description":"Aula que investiga as causas mais comuns de acidentes envolvendo eletricidade e discute formas de preveni-los em casa e na escola.","materials":["Reportagens sobre acidentes elétricos","Imagens de instalações elétricas residenciais","Cartolina para cartazes de segurança"],"steps":["Perguntar aos alunos se já ouviram falar de algum acidente relacionado à eletricidade.","Apresentar e discutir reportagens ou relatos sobre causas comuns desses acidentes.","Em grupos, identificar situações de risco em imagens de instalações elétricas.","Pesquisar e listar medidas de prevenção para cada situação de risco identificada.","Produzir um cartaz de conscientização sobre segurança elétrica.","Expor os cartazes para a turma ou para outras turmas da escola."]},
    {"theme":"Custos ambientais da energia elétrica: debate sobre fontes","curriculumCode":"EF09C07","description":"Aula de debate baseada em dados sobre os impactos ambientais decorrentes da exploração de diferentes recursos usados na geração de energia elétrica, estimando relações de custo-benefício.","materials":["Textos informativos sobre hidrelétricas, termelétricas, eólica e solar","Dados ambientais simplificados de cada fonte","Cartolina para registro de argumentos"],"steps":["Dividir a turma em grupos, cada um representando uma fonte de energia diferente.","Cada grupo pesquisa os impactos ambientais e os benefícios de sua fonte.","Organizar um debate em que cada grupo apresenta argumentos a favor de sua fonte.","Discutir coletivamente qual fonte parece ter melhor relação custo-benefício ambiental.","Registrar em cartaz uma tabela comparativa das fontes discutidas.","Concluir com reflexão sobre a diversificação da matriz energética como estratégia de redução de impactos."]},
    {"theme":"A relação entre eletricidade e magnetismo","curriculumCode":"EF09C08","description":"Aula experimental que demonstra a interação entre corrente elétrica e magnetismo, base do fenômeno do eletromagnetismo.","materials":["Fio de cobre esmaltado","Pilha","Bússola pequena","Fita isolante"],"steps":["Perguntar aos alunos se eles acham que eletricidade e magnetismo têm alguma relação.","Montar um circuito simples com fio e pilha próximo a uma bússola.","Ligar e desligar o circuito, observando o comportamento da agulha da bússola.","Registrar e discutir o que causou o desvio da agulha.","Relacionar a observação ao conceito de campo magnético gerado por corrente elétrica.","Fechar explicando que esse é o princípio por trás de eletroímãs e motores elétricos."]},
    {"theme":"O que influencia a força de um ímã? Investigando o magnetismo","curriculumCode":"EF09C09","description":"Aula investigativa em que os alunos formulam perguntas e testam hipóteses sobre os fatores que alteram a intensidade da força magnética.","materials":["Ímãs de diferentes tamanhos e formatos","Clipes de metal","Régua","Folha de registro"],"steps":["Perguntar aos alunos o que eles acham que torna um ímã 'mais forte'.","Elaborar coletivamente perguntas de investigação sobre fatores que afetam a força magnética.","Testar quantos clipes cada ímã consegue atrair, variando tamanho e distância.","Registrar os dados obtidos em uma tabela simples.","Analisar os resultados e discutir quais fatores realmente influenciaram a força observada.","Concluir com uma lista de fatores confirmados pela investigação."]},
    {"theme":"Visualizando o campo magnético","curriculumCode":"EF09C10","description":"Aula prática que produz evidências visuais da existência de campos magnéticos ao redor de ímãs, usando limalha de ferro e bússola.","materials":["Ímã em barra ou em ferradura","Limalha de ferro","Folha de papel branco","Bússola pequena"],"steps":["Perguntar aos alunos como seria possível 'ver' algo que não se enxerga, como um campo magnético.","Colocar uma folha de papel sobre o ímã e espalhar limalha de ferro levemente sobre ela.","Observar e registrar o padrão formado pela limalha ao redor do ímã.","Usar uma bússola para mapear a direção do campo em diferentes pontos ao redor do ímã.","Comparar o mapeamento com bússola ao padrão da limalha.","Concluir explicando que ambos os métodos produzem evidências da existência do campo magnético."]},
    {"theme":"Eletromagnetismo nos aparelhos de comunicação","curriculumCode":"EF09C11","description":"Aula que aplica conhecimentos de eletromagnetismo para explicar o funcionamento de equipamentos usados na comunicação humana, como campainhas, alto-falantes e celulares.","materials":["Prego de ferro","Fio de cobre esmaltado","Pilha","Clipes de metal","Imagens ou esquema de alto-falante"],"steps":["Perguntar aos alunos como um celular ou um alto-falante consegue produzir som.","Construir um eletroímã simples enrolando fio de cobre em torno de um prego e ligando à pilha.","Testar o eletroímã atraindo clipes de metal e observar que ele só funciona com corrente ligada.","Apresentar um esquema simplificado de como o eletromagnetismo é usado em alto-falantes e campainhas.","Relacionar o experimento a outros equipamentos de comunicação que usam o mesmo princípio.","Fechar com uma lista de aparelhos do cotidiano que dependem do eletromagnetismo."]},
    {"theme":"Radiação eletromagnética na medicina: raios-X e mais","curriculumCode":"EF09C12","description":"Aula que avalia o avanço tecnológico no uso da radiação eletromagnética para diagnóstico e tratamento de doenças, discutindo riscos e benefícios.","materials":["Imagens de exames de raio-X, tomografia e ressonância","Textos informativos sobre uso médico da radiação","Cartolina"],"steps":["Perguntar aos alunos quais exames médicos eles já conhecem que usam algum tipo de radiação.","Apresentar diferentes tipos de radiação eletromagnética usados em diagnóstico e tratamento.","Em grupos, pesquisar um exame ou tratamento específico e como ele funciona.","Discutir os benefícios desses avanços tecnológicos para a saúde.","Debater também os cuidados e riscos associados à exposição à radiação.","Sistematizar as conclusões em um cartaz comparando benefícios e riscos."]},
    {"theme":"Mitos e teorias sobre a origem do Universo","curriculumCode":"EF09C13","description":"Aula que compara explicações de diferentes épocas, culturas e civilizações sobre a origem do Universo e da Terra, valorizando sua relevância histórica e cultural.","materials":["Textos curtos com mitos de criação de diferentes culturas","Texto sobre a teoria do Big Bang","Cartolina para linha do tempo"],"steps":["Perguntar aos alunos se conhecem alguma história sobre como o Universo surgiu.","Apresentar brevemente mitos de criação de diferentes culturas e civilizações.","Apresentar a explicação científica atual, a teoria do Big Bang.","Em grupos, comparar semelhanças e diferenças entre as narrativas apresentadas.","Discutir o valor histórico e cultural de cada tipo de explicação.","Construir uma linha do tempo coletiva situando as diferentes explicações."]},
    {"theme":"Da Terra primitiva à Terra atual: o que mudou?","curriculumCode":"EF09C14","description":"Aula que compara a composição da atmosfera e da crosta da Terra primitiva com a composição atual do planeta, elaborando explicações sobre as transformações ocorridas.","materials":["Esquemas comparativos da atmosfera primitiva e atual","Textos sobre a formação da Terra","Cartolina"],"steps":["Perguntar aos alunos como eles imaginam que era a Terra logo após sua formação.","Apresentar um esquema da composição da atmosfera e da superfície da Terra primitiva.","Comparar com a composição atual do planeta.","Em grupos, levantar hipóteses sobre o que causou essas mudanças ao longo do tempo.","Discutir o papel de fenômenos como vulcanismo e fotossíntese nessas transformações.","Registrar as conclusões em um quadro comparativo Terra primitiva x Terra atual."]},
    {"theme":"A gravidade movendo o Universo","curriculumCode":"EF09C15","description":"Aula que constrói argumentos baseados em evidências para explicar o papel da gravidade no movimento entre galáxias e entre os astros do sistema solar.","materials":["Tecido elástico esticado em um aro","Bolas de diferentes tamanhos e pesos","Imagens do sistema solar e de galáxias"],"steps":["Perguntar aos alunos por que os planetas não saem flutuando pelo espaço.","Usar o tecido elástico e bolas de diferentes massas para simular a curvatura causada pela gravidade.","Observar como uma bola menor orbita ao redor da mais pesada no tecido.","Relacionar a simulação ao movimento dos planetas ao redor do Sol.","Discutir como a gravidade também atua entre galáxias em maior escala.","Concluir com argumentos, baseados na simulação, sobre o papel da gravidade nesses movimentos."]},
    {"theme":"Explorando o espaço: benefícios e desafios","curriculumCode":"EF09C16","description":"Aula que coleta e interpreta informações sobre as implicações da exploração espacial pelo ser humano, discutindo avanços tecnológicos e desafios envolvidos.","materials":["Reportagens sobre missões espaciais","Imagens de satélites e estações espaciais","Cartolina para registro"],"steps":["Perguntar aos alunos o que eles sabem sobre exploração espacial.","Apresentar exemplos de missões espaciais e suas motivações.","Em grupos, pesquisar uma missão específica e seus resultados.","Levantar benefícios tecnológicos trazidos por essas explorações para o dia a dia.","Discutir também os custos, riscos e questionamentos éticos envolvidos.","Sistematizar as conclusões em um cartaz de benefícios x desafios."]},
    {"theme":"Atmosfera primitiva e o surgimento da vida","curriculumCode":"EF09C17","description":"Aula que aplica conhecimentos sobre efeito estufa e camada de ozônio para construir explicações sobre as condições que permitiram a origem da vida na Terra.","materials":["Esquema da atmosfera primitiva","Textos sobre efeito estufa natural e camada de ozônio","Cartolina"],"steps":["Retomar o que os alunos já sabem sobre a composição da Terra primitiva.","Apresentar o papel do efeito estufa natural na manutenção de temperaturas favoráveis à vida.","Explicar como a formação da camada de ozônio permitiu a proteção contra radiação ultravioleta.","Em grupos, relacionar essas condições atmosféricas ao surgimento dos primeiros seres vivos.","Discutir por que essas condições foram fundamentais para a vida se estabelecer.","Sistematizar as explicações construídas em um esquema coletivo."]},
    {"theme":"Explicações históricas e culturais sobre a origem da vida","curriculumCode":"EF09C18","description":"Aula que apresenta explicações formuladas em diferentes épocas, culturas e civilizações sobre a origem da vida na Terra, valorizando sua relevância histórica e social.","materials":["Textos de diferentes tradições sobre a origem da vida","Linha do tempo impressa","Cartolina"],"steps":["Perguntar aos alunos que explicações eles já ouviram sobre como a vida começou na Terra.","Apresentar explicações de diferentes culturas e momentos históricos sobre a origem da vida.","Em grupos, pesquisar e aprofundar uma dessas explicações.","Compartilhar as pesquisas com a turma, destacando o contexto cultural de cada uma.","Discutir a importância de conhecer diferentes visões sobre esse tema.","Organizar as explicações estudadas em uma linha do tempo coletiva."]},
    {"theme":"O experimento que derrubou a geração espontânea","curriculumCode":"EF09C19","description":"Aula que usa um experimento simplificado e a história da ciência para questionar a validade da ideia de geração espontânea da vida.","materials":["Dois frascos com caldo nutritivo (caldo de carne ou similar)","Filtro ou tampa para um dos frascos","Texto sobre os experimentos de Redi e Pasteur"],"steps":["Perguntar aos alunos se eles acham que a vida pode surgir espontaneamente de matéria não viva.","Apresentar a ideia antiga de geração espontânea e como ela era aceita no passado.","Montar dois frascos com caldo nutritivo, um aberto e outro protegido, e observá-los ao longo dos dias.","Registrar as diferenças observadas entre os dois frascos.","Relacionar o resultado aos experimentos históricos de Francesco Redi e Louis Pasteur.","Concluir discutindo como evidências experimentais podem derrubar ideias antigas."]},
    {"theme":"Lendo o tempo nos fósseis: escalas da história da vida","curriculumCode":"EF09C20","description":"Aula que utiliza dados e representações sobre o registro fóssil para determinar escalas de tempo envolvidas na história da vida na Terra.","materials":["Imagens de fósseis de diferentes períodos","Linha do tempo geológica impressa","Régua","Cartolina"],"steps":["Perguntar aos alunos como os cientistas sabem a idade aproximada de um fóssil.","Apresentar uma linha do tempo geológica simplificada com as principais eras.","Em grupos, organizar imagens de fósseis na ordem cronológica correspondente.","Construir uma linha do tempo em escala, posicionando os fósseis estudados.","Discutir a diferença de escala entre a história da vida e a história humana.","Concluir relacionando o registro fóssil às mudanças na vida ao longo do tempo geológico."]},
    {"theme":"Genético, hereditário, congênito ou adquirido? Diferenciando características","curriculumCode":"EF09C21","description":"Aula que diferencia características genéticas, hereditárias, congênitas e adquiridas por meio da análise de exemplos do cotidiano.","materials":["Fichas com exemplos de características humanas","Cartaz dividido em quatro categorias","Canetinhas"],"steps":["Apresentar exemplos de características humanas, como cor dos olhos, uma cicatriz e uma habilidade aprendida.","Explicar as diferenças entre características genéticas, hereditárias, congênitas e adquiridas.","Em grupos, classificar as fichas de exemplos nas categorias corretas em um cartaz.","Discutir casos que geram dúvida, como uma malformação congênita não hereditária.","Pedir que cada aluno crie um exemplo próprio para uma das categorias.","Socializar os exemplos criados e verificar a classificação coletivamente."]},
    {"theme":"Reprodução assexuada x sexuada: de onde vem a variação genética","curriculumCode":"EF09C22","description":"Aula que desenvolve modelos simples para descrever as diferenças entre reprodução assexuada e sexuada, relacionando-as à variação genética entre indivíduos.","materials":["Imagens de organismos com reprodução assexuada e sexuada","Massinha de modelar de duas cores","Cartolina"],"steps":["Apresentar exemplos de organismos que se reproduzem de forma assexuada e sexuada.","Explicar que na reprodução assexuada a prole é geneticamente idêntica ao progenitor.","Usar massinha de duas cores para modelar a combinação de características de dois progenitores na reprodução sexuada.","Comparar o resultado do modelo com a ideia de clone da reprodução assexuada.","Discutir por que a reprodução sexuada gera mais variação genética entre os descendentes.","Concluir relacionando a variação genética à capacidade de adaptação das populações."]},
    {"theme":"Ambiente, genética e seleção natural moldando as populações","curriculumCode":"EF09C23","description":"Aula que constrói explicações sobre como fatores ambientais e genéticos influenciam o crescimento dos organismos e as características das populações, aplicando ideias de seleção natural.","materials":["Imagens de exemplos clássicos de seleção natural (mariposas, tentilhões de Darwin)","Textos de apoio sobre o tema","Cartolina"],"steps":["Apresentar um caso clássico de seleção natural, como as mariposas que mudaram de cor conforme o ambiente.","Discutir quais fatores ambientais e genéticos estavam envolvidos nesse caso.","Em grupos, analisar um segundo exemplo e identificar os mesmos tipos de fatores.","Relacionar os exemplos estudados aos princípios da seleção natural.","Discutir como esses fatores também influenciam o crescimento e as características de populações humanas.","Sistematizar as explicações construídas em um esquema coletivo."]},
    {"theme":"Seleção artificial e engenharia genética: riscos e benefícios","curriculumCode":"EF09C24","description":"Aula que reúne informações sobre a interferência da ação humana e da tecnologia na herança de características desejáveis em organismos, avaliando riscos e benefícios envolvidos.","materials":["Imagens de raças de cães, gatos ou plantas obtidas por seleção artificial","Textos sobre alimentos transgênicos e engenharia genética","Cartolina para debate"],"steps":["Perguntar aos alunos se conhecem exemplos de raças de animais ou plantas criadas pelo ser humano.","Apresentar o conceito de seleção artificial com exemplos históricos, como raças de cães.","Introduzir de forma acessível o conceito de engenharia genética e seus usos atuais, como transgênicos.","Em grupos, pesquisar um exemplo de seleção artificial ou engenharia genética e seus efeitos.","Debater os riscos e benefícios éticos e ambientais dessas técnicas.","Concluir com produção coletiva de um cartaz sobre bioética e manipulação genética."]},
  ],
  geografia: [
    {"theme":"Meu bairro, meu mundo: o local dentro do global","curriculumCode":"EF09G01","description":"Aula de debate sobre como o cotidiano local está conectado a processos globais, explorando a diversidade de pessoas e lugares que formam o mundo contemporâneo.","materials":["Notícias de jornal impressas ou recortadas","Mapa-múndi","Cartolina para registro das ideias","Quadro branco"],"steps":["Apresentar uma notícia local e uma notícia global relacionadas ao mesmo tema (ex.: consumo, migração, tecnologia)","Dividir a turma em grupos para identificar conexões entre o fato local e o fenômeno global","Promover um debate estruturado sobre quem são os sujeitos afetados em cada escala","Registrar coletivamente no quadro as conclusões sobre a relação local-global","Encerrar com produção de um pequeno texto individual sobre um exemplo pessoal dessa conexão"]},
    {"theme":"Globalização e mundialização: dois olhares sobre a integração mundial","curriculumCode":"EF09G02","description":"Aula que compara diferentes interpretações teóricas sobre a integração econômica, política e cultural do mundo, analisando fatos e situações concretas.","materials":["Textos comparativos sobre globalização e mundialização","Projetor ou cartazes","Roteiro de estudo dirigido"],"steps":["Introduzir os conceitos de globalização e mundialização de forma contrastada","Apresentar estudos de caso (economia, política, cultura) para análise em grupos","Solicitar que cada grupo classifique o caso segundo uma das interpretações","Realizar plenária comparando as conclusões dos grupos","Sistematizar em um quadro-síntese as diferenças entre as duas abordagens"]},
    {"theme":"Investigando o mundo: fontes escritas e imagéticas em Geografia","curriculumCode":"EF09G03","description":"Aula prática de letramento geográfico voltada ao uso de diferentes fontes de informação — textuais e visuais — e a procedimentos básicos de registro de pesquisa.","materials":["Reportagens, gráficos e fotografias diversas","Fichas de registro","Lápis e caneta"],"steps":["Apresentar diferentes tipos de fontes geográficas (textos, imagens, gráficos, mapas)","Orientar os alunos sobre critérios básicos de confiabilidade de uma fonte","Propor pesquisa em pequenos grupos sobre um tema geográfico atual","Ensinar um modelo simples de ficha de registro de fontes consultadas","Solicitar apresentação breve de cada grupo sobre as fontes utilizadas e suas conclusões"]},
    {"theme":"África na Nova Ordem Mundial","curriculumCode":"EF09G04","description":"Aula que analisa as transformações territoriais, políticas e econômicas do continente africano diante da globalização e da reconfiguração das relações internacionais.","materials":["Mapa político da África","Linha do tempo histórica","Textos sobre economia africana contemporânea"],"steps":["Contextualizar historicamente a formação territorial da África pós-colonial","Apresentar dados atuais sobre economia e política de países africanos","Dividir a turma em grupos para estudar diferentes sub-regiões do continente","Discutir como a globalização reconfigura essas relações territoriais e econômicas","Elaborar um mural coletivo com os principais reordenamentos identificados"]},
    {"theme":"Nacionalismos e separatismos: o caso do Oriente Médio","curriculumCode":"EF09G05","description":"Aula que identifica e discute os principais movimentos nacionalistas e separatistas do mundo contemporâneo, com foco especial na região do Oriente Médio.","materials":["Mapa político do Oriente Médio","Reportagens sobre conflitos regionais","Quadro comparativo impresso"],"steps":["Explicar os conceitos de nacionalismo e separatismo com exemplos históricos","Localizar no mapa os principais focos de tensão no Oriente Médio","Apresentar em grupos estudos de caso de movimentos separatistas específicos","Debater as causas territoriais, étnicas e religiosas desses movimentos","Produzir uma síntese comparativa entre diferentes casos estudados"]},
    {"theme":"Europa e Ásia: um continente ou dois?","curriculumCode":"EF09G06","description":"Aula que analisa os elementos físico-naturais da Eurásia e discute os critérios histórico-geográficos que levaram à divisão convencional entre Europa e Ásia.","materials":["Mapa físico da Eurásia","Atlas geográfico","Imagens de relevo e hidrografia da região"],"steps":["Apresentar o mapa físico da Eurásia como unidade continental","Levantar com a turma por que existe a divisão convencional em dois continentes","Analisar em grupos os critérios históricos e culturais dessa divisão","Comparar características físico-naturais de sub-regiões da Eurásia","Discutir coletivamente se a divisão é geográfica, histórica ou cultural"]},
    {"theme":"Paisagens e usos da terra pelo mundo","curriculumCode":"EF09G07","description":"Aula que explora as características físico-naturais e as formas de ocupação e uso da terra em diferentes regiões da Europa, Ásia, África e Oceania.","materials":["Imagens de paisagens de diferentes continentes","Mapa-múndi físico","Fichas descritivas por região"],"steps":["Apresentar imagens de paisagens variadas dos quatro continentes estudados","Formar grupos, cada um responsável por analisar uma região específica","Orientar a identificação de características naturais e formas de uso da terra","Solicitar apresentação comparativa entre as regiões estudadas","Fechar com discussão sobre como o ambiente influencia as formas de ocupação"]},
    {"theme":"Regionalizando o mundo: blocos econômicos e políticos","curriculumCode":"EF09G08","description":"Aula que discute os diferentes critérios usados para regionalizar o mundo, com base na formação de blocos econômicos e políticos internacionais.","materials":["Mapa dos principais blocos econômicos mundiais","Textos informativos sobre blocos regionais","Cartolina e canetinhas"],"steps":["Apresentar exemplos de diferentes critérios de regionalização (econômico, cultural, político)","Introduzir os principais blocos econômicos e políticos existentes","Dividir a turma em grupos para pesquisar um bloco específico","Solicitar que cada grupo apresente os objetivos e países-membros do bloco","Debater coletivamente vantagens e limites da regionalização por blocos"]},
    {"theme":"Lendo o relevo: taxonomia e representações visuais","curriculumCode":"EF09G09","description":"Aula que trabalha a classificação (taxonomia) dos tipos de relevo e a interpretação de blocos-diagramas e esquemas visuais relativos à Europa e à Ásia.","materials":["Blocos-diagramas impressos","Atlas de relevo","Massa de modelar (opcional para maquete de relevo)"],"steps":["Apresentar a classificação básica dos tipos de relevo (planícies, planaltos, montanhas)","Mostrar exemplos de blocos-diagramas e esquemas de relevo da Europa e Ásia","Orientar a leitura passo a passo de um bloco-diagrama em grupo","Propor exercício de identificação de tipos de relevo em novos esquemas","Finalizar com produção de um esquema simples de relevo por grupo"]},
    {"theme":"Mapas fora do padrão: cartogramas e anamorfoses","curriculumCode":"EF09G10","description":"Aula prática de produção e interpretação de cartogramas, mapas esquemáticos (croquis) e anamorfoses sobre Europa, Ásia, África e Oceania.","materials":["Exemplos impressos de cartogramas e anamorfoses","Papel sulfite","Lápis de cor e réguas"],"steps":["Explicar a diferença entre mapa convencional, cartograma e anamorfose","Analisar coletivamente um exemplo de cartograma populacional mundial","Orientar a produção de um croqui simples de uma das regiões estudadas","Propor a criação de uma anamorfose baseada em um dado estatístico à escolha","Expor os trabalhos produzidos para comparação entre os grupos"]},
    {"theme":"Projeções cartográficas e temas sociais e ambientais","curriculumCode":"EF09G11","description":"Aula que identifica diferentes projeções cartográficas e anamorfoses utilizadas para representar questões sociais, ambientais, naturais e de saúde.","materials":["Exemplos de diferentes projeções cartográficas (Mercator, Peters, etc.)","Mapas temáticos de saúde e meio ambiente","Projetor"],"steps":["Apresentar diferentes projeções cartográficas e suas distorções características","Discutir como a escolha da projeção pode influenciar a interpretação de um mapa","Analisar em grupos mapas temáticos sobre saúde ou meio ambiente","Solicitar que os grupos identifiquem qual projeção foi usada em cada mapa","Debater coletivamente os impactos políticos das escolhas cartográficas"]},
    {"theme":"Fluxos que movem o mundo: pessoas e capitais","curriculumCode":"EF09G12","description":"Aula que trabalha a compreensão de fluxos populacionais e de capitais por meio da produção e interpretação de mapas de fluxos, cartogramas, gráficos e textos multimodais.","materials":["Mapas de fluxos migratórios e financeiros","Gráficos e tabelas de dados","Papel para produção de mapas de fluxo"],"steps":["Apresentar exemplos de mapas de fluxos populacionais e de capitais","Explicar como interpretar setas, espessuras e direções em mapas de fluxo","Propor análise em grupos de um gráfico ou tabela sobre migrações ou investimentos","Orientar a produção de um mapa de fluxo simples sobre um tema escolhido","Encerrar com apresentação e discussão dos mapas produzidos pelos grupos"]},
    {"theme":"Recursos naturais pelo mundo: formação e distribuição","curriculumCode":"EF09G13","description":"Aula que trabalha a formação dos recursos naturais e sua distribuição espacial na Europa, Ásia, África e Oceania.","materials":["Mapa de recursos naturais mundial","Textos sobre formação geológica de recursos","Atlas geográfico"],"steps":["Explicar os principais processos de formação de recursos naturais","Apresentar o mapa de distribuição de recursos nos quatro continentes","Dividir a turma em grupos, cada um analisando um tipo de recurso","Solicitar que localizem no mapa onde esse recurso é mais abundante","Fechar com discussão sobre desigualdades na distribuição de recursos"]},
    {"theme":"Brasil nas conferências ambientais internacionais","curriculumCode":"EF09G14","description":"Aula que reconhece o papel do Brasil em grandes conferências e acordos internacionais sobre meio ambiente, discutindo seus compromissos e desafios.","materials":["Linha do tempo de conferências ambientais (Rio-92, COPs, etc.)","Textos sobre acordos internacionais","Quadro branco"],"steps":["Apresentar uma linha do tempo das principais conferências ambientais mundiais","Destacar a participação e os compromissos assumidos pelo Brasil em cada uma","Formar grupos para pesquisar um acordo específico e seus objetivos","Promover apresentação e discussão sobre o cumprimento desses compromissos","Encerrar com reflexão coletiva sobre o papel do Brasil na governança ambiental global"]},
    {"theme":"Natureza, ambiente e ação humana: rumo à sustentabilidade","curriculumCode":"EF09G15","description":"Aula que estabelece relações entre natureza, ambiente e atividades humanas, utilizando modelos e exemplos voltados ao desenvolvimento sustentável.","materials":["Estudos de caso sobre impactos ambientais","Modelos ou esquemas de desenvolvimento sustentável","Cartolina para mapa conceitual"],"steps":["Introduzir os conceitos de natureza, ambiente e atividade antrópica","Apresentar um modelo ou esquema simples de desenvolvimento sustentável","Propor análise em grupos de um caso real de impacto ambiental humano","Solicitar que os grupos identifiquem alternativas sustentáveis para o caso","Construir coletivamente um mapa conceitual relacionando os três elementos"]},
    {"theme":"Recursos minerais: quem tem a matéria-prima, quem tem a tecnologia","curriculumCode":"EF09G16","description":"Aula que trabalha o processo de formação dos recursos minerais e compara a situação econômica entre países produtores de matéria-prima e países detentores de tecnologia.","materials":["Mapa de jazidas minerais mundiais","Tabela comparativa de países produtores e consumidores","Textos sobre a cadeia produtiva mineral"],"steps":["Explicar de forma simplificada o processo de formação de recursos minerais","Apresentar mapa com principais países produtores de minerais estratégicos","Comparar em grupos a situação de países exportadores de matéria-prima e países industrializados","Discutir as consequências dessa divisão para trabalho e desenvolvimento","Sistematizar em quadro comparativo as diferenças identificadas"]},
    {"theme":"Blocos econômicos e a nova ordem geopolítica","curriculumCode":"EF09G17","description":"Aula que analisa o papel dos blocos econômicos e geopolíticos considerando a divisão internacional do trabalho e a nova ordem econômica mundial.","materials":["Mapa dos blocos econômicos e geopolíticos","Textos sobre divisão internacional do trabalho","Quadro branco"],"steps":["Retomar o conceito de divisão internacional do trabalho","Apresentar os principais blocos econômicos e geopolíticos atuais","Formar grupos para analisar como cada bloco se posiciona nessa divisão","Debater coletivamente os efeitos da nova ordem econômica sobre diferentes países","Produzir uma síntese sobre o papel geopolítico dos blocos estudados"]},
    {"theme":"Produção, circulação e consumo na Europa","curriculumCode":"EF09G18","description":"Aula que analisa diferentes formas de produção, circulação e consumo para compreender a organização política e econômica das sociedades europeias.","materials":["Mapa econômico da Europa","Textos sobre cadeias produtivas europeias","Gráficos de comércio e consumo"],"steps":["Apresentar as principais características econômicas dos países europeus","Explicar as etapas de produção, circulação e consumo com exemplos europeus","Formar grupos para estudar a cadeia produtiva de um produto específico","Relacionar essa cadeia com a organização política e econômica do país estudado","Encerrar com apresentação comparativa entre os produtos analisados"]},
    {"theme":"Indústria e trabalho: transformações técnicas pelo mundo","curriculumCode":"EF09G19","description":"Aula que relaciona as mudanças técnicas e científicas decorrentes da industrialização com as transformações no mundo do trabalho em diferentes regiões.","materials":["Linha do tempo da industrialização","Textos sobre automação e trabalho","Imagens de fábricas em diferentes períodos históricos"],"steps":["Apresentar uma linha do tempo das revoluções industriais e suas inovações técnicas","Discutir como cada mudança técnica impactou as relações de trabalho","Formar grupos para comparar essas transformações em diferentes regiões do mundo","Propor reflexão sobre os efeitos atuais da automação sobre o emprego","Fechar com debate coletivo sobre perspectivas futuras do trabalho industrial"]},
  ],
  historia: [
    {"theme":"O capitalismo no dia a dia: mercado, consumo e comércio internacional","curriculumCode":"EF09H01","description":"Aula que discute como o capitalismo se manifesta nas relações sociais cotidianas atuais, envolvendo mercado, consumo, investimentos e comércio internacional.","materials":["Notícias sobre economia e consumo","Rótulos ou embalagens de produtos importados","Cartolina","Lousa e giz/marcador"],"steps":["Perguntar aos alunos onde eles percebem o capitalismo no dia a dia","Apresentar exemplos de produtos, marcas e serviços ligados ao mercado global","Formar grupos para identificar elementos capitalistas em situações cotidianas (compras, propagandas, aplicativos)","Discutir a diferença entre consumo, investimento e comércio internacional a partir dos exemplos","Promover apresentação dos grupos com debate coletivo","Encerrar relacionando os exemplos estudados ao conceito de capitalismo como sistema"]},
    {"theme":"A expansão do capitalismo entre os séculos XIX e XX","curriculumCode":"EF09H02","description":"Aula que analisa como o sistema capitalista se expandiu e se consolidou como modelo econômico hegemônico entre os séculos XIX e XX.","materials":["Linha do tempo do capitalismo","Mapa-múndi","Textos de apoio sobre expansão econômica","Cartolina"],"steps":["Retomar brevemente a origem do capitalismo estudada em anos anteriores","Apresentar, com apoio de linha do tempo, momentos-chave da expansão capitalista nos séculos XIX e XX","Localizar no mapa-múndi regiões que passaram a integrar o sistema capitalista global","Formar grupos para relacionar um evento histórico à expansão do capitalismo","Apresentar as conclusões dos grupos à turma","Fechar com registro escrito sobre como o capitalismo se tornou sistema dominante"]},
    {"theme":"Capitalismo, imperialismo e as grandes guerras mundiais","curriculumCode":"EF09H03","description":"Aula que relaciona a expansão capitalista com o imperialismo, o neocolonialismo, os regimes totalitários e as duas guerras mundiais.","materials":["Mapa dos impérios coloniais no início do século XX","Textos sobre imperialismo e totalitarismo","Linha do tempo das guerras mundiais","Cartolina"],"steps":["Apresentar o conceito de imperialismo e sua ligação com a expansão capitalista","Explorar, em mapa, a divisão de territórios entre potências imperialistas","Formar grupos para relacionar imperialismo, totalitarismo e uma das guerras mundiais","Solicitar que os grupos expliquem como essas relações levaram a conflitos globais","Organizar apresentação dos grupos em ordem cronológica","Encerrar com debate sobre as consequências desses processos para o mundo atual"]},
    {"theme":"Revoluções socialistas do século XX","curriculumCode":"EF09H04","description":"Aula que estuda os processos revolucionários do século XX, com destaque para os movimentos e as revoluções socialistas.","materials":["Textos sobre revoluções socialistas (ex.: Revolução Russa)","Linha do tempo do século XX","Imagens de líderes e movimentos revolucionários","Cartolina"],"steps":["Contextualizar as condições sociais que motivaram movimentos revolucionários no século XX","Apresentar, com apoio de linha do tempo, exemplos de revoluções socialistas","Formar grupos, cada um estudando um processo revolucionário específico","Solicitar que os grupos identifiquem causas, líderes e transformações provocadas","Apresentar as pesquisas dos grupos à turma","Fechar com debate sobre os ideais socialistas e seus impactos históricos"]},
    {"theme":"Neocolonialismo, descolonização e novas fronteiras na África e na Ásia","curriculumCode":"EF09H05","description":"Aula que discute a violência das políticas neocoloniais aplicadas a países africanos e asiáticos e o processo de descolonização que redefiniu fronteiras no mapa-múndi atual.","materials":["Mapa da África e da Ásia antes e depois da descolonização","Textos sobre neocolonialismo","Cartolina","Linha do tempo da descolonização"],"steps":["Apresentar o conceito de neocolonialismo e suas diferenças em relação ao colonialismo anterior","Explorar mapas comparando fronteiras africanas e asiáticas antes e depois da descolonização","Formar grupos para pesquisar o processo de independência de um país africano ou asiático","Discutir formas de violência e resistência presentes nesses processos","Compartilhar as pesquisas em apresentação para a turma","Encerrar relacionando as fronteiras atuais aos processos históricos estudados"]},
    {"theme":"Do campo à cidade: transformações econômicas do Brasil no século XX","curriculumCode":"EF09H06","description":"Aula que analisa as transformações econômicas da sociedade brasileira ao longo do século XX, com foco nos contrastes entre o mundo rural e a expansão urbana.","materials":["Gráficos de crescimento urbano no Brasil","Fotografias de cidades e áreas rurais em diferentes décadas","Cartolina","Mapa do Brasil"],"steps":["Perguntar aos alunos o que sabem sobre êxodo rural e crescimento das cidades","Apresentar gráficos e imagens sobre a urbanização brasileira ao longo do século XX","Formar grupos para comparar características do mundo rural e do mundo urbano em diferentes períodos","Discutir causas econômicas que impulsionaram a migração para as cidades","Apresentar as comparações dos grupos à turma","Fechar com reflexão sobre contrastes urbano-rurais ainda presentes hoje"]},
    {"theme":"Ditaduras e redemocratização na América Latina","curriculumCode":"EF09H07","description":"Aula que identifica e analisa a implantação de governos ditatoriais em países da América Latina e os processos que levaram à redemocratização.","materials":["Mapa da América Latina","Linha do tempo das ditaduras latino-americanas","Textos sobre redemocratização","Cartolina"],"steps":["Apresentar o contexto histórico da implantação de ditaduras na América Latina","Localizar no mapa países que viveram regimes ditatoriais no século XX","Formar grupos para pesquisar a ditadura de um país específico e seu processo de redemocratização","Solicitar que os grupos identifiquem semelhanças e diferenças entre os casos estudados","Apresentar as pesquisas em roda de conversa","Encerrar com debate sobre a importância da democracia a partir dos casos estudados"]},
    {"theme":"Laços históricos entre o Brasil e os países africanos de língua portuguesa","curriculumCode":"EF09H08","description":"Aula que compara e relaciona aspectos da história dos países africanos de língua portuguesa com elementos da cultura brasileira.","materials":["Mapa dos países africanos de língua portuguesa (PALOP)","Textos e músicas sobre cultura afro-brasileira e africana","Cartolina"],"steps":["Apresentar no mapa os países africanos de língua portuguesa e sua história comum com o Brasil","Explorar exemplos de expressões culturais compartilhadas (língua, música, culinária, religiosidade)","Formar grupos para pesquisar um país africano de língua portuguesa e suas conexões com o Brasil","Solicitar que os grupos apresentem semelhanças e diferenças culturais identificadas","Promover roda de apresentação dos grupos","Fechar com discussão sobre a importância desses laços históricos para a identidade brasileira"]},
    {"theme":"Lutas operárias, feministas e étnico-raciais no século XX","curriculumCode":"EF09H09","description":"Aula que reconhece e discute lutas operárias, feministas e étnico-raciais ocorridas no Brasil e no mundo ao longo do século XX.","materials":["Textos e imagens sobre movimentos operários, feministas e negros","Biografias curtas de lideranças desses movimentos","Cartolina"],"steps":["Apresentar o conceito de luta social e sua relevância no século XX","Explorar exemplos de movimentos operários, feministas e étnico-raciais no Brasil e no mundo","Formar grupos, cada um pesquisando um desses movimentos e suas principais conquistas","Solicitar que os grupos relacionem as lutas estudadas a direitos existentes hoje","Apresentar as pesquisas dos grupos à turma","Encerrar com debate sobre pautas dessas lutas que permanecem atuais"]},
    {"theme":"A economia globalizada no cotidiano dos jovens","curriculumCode":"EF09H10","description":"Aula que identifica a presença da economia capitalista global no dia a dia e no imaginário dos jovens atualmente, incluindo marcas, tecnologia e redes sociais.","materials":["Exemplos de marcas e produtos globais","Prints de aplicativos e redes sociais","Cartolina","Lousa e giz/marcador"],"steps":["Perguntar aos alunos quais marcas, aplicativos e produtos globais fazem parte do dia a dia deles","Apresentar exemplos de como a economia global influencia hábitos de consumo e comportamento","Formar grupos para mapear presenças da economia global no cotidiano da turma","Discutir como essas influências moldam desejos, identidades e imaginário juvenil","Apresentar os mapeamentos dos grupos à turma","Fechar com reflexão crítica sobre consumo consciente diante da economia globalizada"]},
    {"theme":"Fontes históricas: textos, imagens e objetos em seu contexto de produção","curriculumCode":"EF09H11","description":"Aula que trabalha como textos, imagens, objetos e outras produções humanas se relacionam com seus autores, locais de produção e tempo histórico.","materials":["Diversas fontes históricas (textos, fotografias, objetos ou reproduções)","Ficha de análise de fontes","Cartolina"],"steps":["Apresentar diferentes tipos de fontes históricas trazidas para a aula","Explicar a importância de identificar autor, local e época de produção de uma fonte","Formar grupos, cada um analisando uma fonte com apoio de ficha orientadora","Solicitar que os grupos expliquem o que a fonte revela sobre seu contexto de produção","Promover apresentação das análises à turma","Encerrar com discussão sobre como o contexto influencia a interpretação de uma fonte"]},
    {"theme":"Representações de sujeitos históricos no tempo e no espaço","curriculumCode":"EF09H12","description":"Aula que diferencia representações de sujeitos históricos, contextualizando-as de acordo com o tempo e o espaço em que foram produzidas.","materials":["Diferentes representações de um mesmo sujeito histórico (pinturas, fotos, textos)","Cartolina","Textos de apoio sobre contexto histórico"],"steps":["Apresentar diferentes representações de um mesmo sujeito ou grupo histórico","Perguntar aos alunos o que muda entre as representações apresentadas","Formar grupos para comparar as representações e identificar época e local de produção de cada uma","Discutir como interesses e contextos diferentes geram representações distintas","Apresentar as comparações dos grupos à turma","Fechar com produção de um pequeno texto sobre a importância de contextualizar representações históricas"]},
  ],
};
